window.dataContent = window.dataContent || {};
window.dataContent = Object.assign(window.dataContent, {"语法-L":{"type":"grammar","title":"语法篇：完整目录","sections":[{"category":"本身","items":[{"point":"～そのもの","explain":"一般加在表示人、物(具体事物或抽象事物)的后面。","example":"例：問題点を指摘した彼自体も、問題を解決する意欲はあまりない。 例：中身自体はあまり重くないが、箱は重い。","translation":"译文：他指出了问题的所在，但是就连他自己也没有积极解决问题的意思。 译文：里面东西本身不沉，但是箱子却很沉。"}]},{"category":"比较","items":[{"point":"～よりも","explain":"一般加在表示人的后面。","example":"例：それは彼自身の問題だ。","translation":"译文：那是他自身的问题。"},{"point":"～とは比べ物にはならない","explain":"一般加在表示物(具体事物或抽象事物)的后面。","example":"例：発想そのものは悪くないが、いい結果にはならなかった。","translation":"译文：出发点本身不错，但是却没有成为好的结果。"},{"point":"～には適わない","explain":"よりも是表示比较的より的正式表达方式。 意思是：比～。","example":"例：聞くよりも自分の目で見た方がいい。","translation":"译文：耳闻不如目睹。"},{"point":"～には匹敵できない","explain":"との意思是“和”；は表示强调；「比べ物」的意思是“比较的东西”；「成らない」的意思是“不成为”。 全意为：不能成为和～相比较的东西。 前面要用名词。","example":"例：京都の寒さは北海道とは比べ物にはならない。","translation":"译文：京都的寒冷与北海道不能相提并论。"},{"point":"～には及ばない","explain":"に表示对象；は表示强调；「敵わない」的意思是“敌不过～”。 前面要用名词。 ：还是比不上天才。","example":"例：私の日本語の語学力は彼の半分には及ばない。","translation":"解释：我的日语水平不及他的一半。"},{"point":"～にこしたことはない","explain":"に表示对象；は表示强调；「匹敵できない」的意思是“不能匹敌”。 全意为：不能与～相匹敌。前面要用名词。","example":"例：私の実力は彼のには匹敵できない。","translation":"解释：我的实力不能与他相匹敌。"},{"point":"～にもまして","explain":"に表示对象；は表示强调；「及ばない」的意思是“不及”。 前面要用名词。","example":"例：私の日本語の語学力は彼の半分には及ばない。","translation":"解释：我的日语水平不及他的一半。"},{"point":"～よりましだ","explain":"に表示对象；「こした」是「越す」的过去式；「ことはない」的意思是“没有～的事情”。 此处用过去式是日式思维的一种表达方式：自动词在修饰名词的时候要变成过去式，此时日语的自动词翻译成汉语是形容词。 全意为：没有超过～的了。 前面要用名词。","example":"例：応募の締め切りは明日ですが、早めに出すにこしたことはない。","translation":"译文：明天是申请截止日期，没有比提早上交更好的了。"}]},{"category":"并不是","items":[{"point":"～わけではない","explain":"に表示对象；も表示强调；「まして」是动词「増す」的て形，表示中顿。 通常前面用“前、以前、昨年”等表示时间的名词。","example":"例：彼女は前にもまして勉強に励んでいる。","translation":"译文：她比以前更努力学习了。"}]},{"category":"不","items":[{"point":"～ず","explain":"より的意思是“比”；「まし」是「増す」的连用形，作名词使用。 意思是：比～强一点儿。比喻两者水平都不高。","example":"例：知らないより少し知った方がましだ。","translation":"译文：稍微知道些比不知道强点儿。"},{"point":"～ずに","explain":"「訳」的意思是“道理”。 「わけではない」的意思是“并不是～”。 注：～わけだ。请参照“也就是说”。","example":"例：足を怪我していますが、全く歩けないわけではない。","translation":"译文：脚受伤了，但也并不是完全不能走路。"},{"point":"～まい","explain":"。请参照“可能性”。","example":"例：田中さんがこのことに賛成することはあるまい。 例：親に経済的な負担をかけまいと思って、学費と生活費をアルバイトで稼いでいる。","translation":"译文：田中不会赞成这件事吧。 译文：想着绝不给父母增加经济负担，在打工挣学费和生活费。"}]},{"category":"不～不行","items":[{"point":"～ずにはいられない","explain":"。请参照“应该”。","example":"例：子供は外で騒いでいるので、注意せずにはいられない。","translation":"译文：孩子们在外面吵闹，不管他们不行。"},{"point":"～ずにはすまない","explain":"ず是ない的古语形式。用于两个短句中的前一个句子之后。 ず前面接动词的未然形，接する时变成せず。","example":"例：なかなか場所が見つからず、大変だった。","translation":"译文：怎么也找不到地方，费了半天劲。"},{"point":"～ずにはおかない","explain":"ず是ない的古语形式；に表示副词。 ず前面接动词的未然形，接する时变成せず。 ず和ずに的不同点在于ず后面一般要有逗号，把一个句子分为两个句子。而ずに是副词，后面马上要接动词。 それで、買わずに済んだ。","example":"例：ずっと欲しかったキーホルダーは誕生日のお祝いで友達からもらった。","translation":"译文：朋友给了我一直想要的钥匙链作为生日礼物。所以不用买了。"}]},{"category":"不可以","items":[{"point":"～てはいけない","explain":"まい有两个意思：一个是不ないでしょう，“不~吧”；另一个意思是“决不～”。 接在五段动词的终止形后，一段动词和カ变动词的未然形后，サ动词为すまい、します或するまい的三种形式中的任何一种。","example":"例：田中さんがこのことに賛成することはあるまい。 例：親に経済的な負担をかけまいと思って、学費と生活費をアルバイトで稼いでいる。","translation":"译文：田中不会赞成这件事吧。 译文：想着绝不给父母增加经济负担，在打工挣学费和生活费。"},{"point":"～てはならない","explain":"ず是ない的古语形式；に表示副词；は表示强调；いられない是「いる」的可能形的否定。 意思是：不做某事的话就待不住。","example":"例：子供は外で騒いでいるので、注意せずにはいられない。","translation":"译文：孩子们在外面吵闹，不管他们不行。"},{"point":"～べからざる","explain":"ず是ない的古语形式；に表示副词；は表示强调；すまない是表示完成的「済む」的否定形式。","example":"","translation":""},{"point":"～べからず","explain":"「まじき」是表示决不做某事的「まい」的古语连体形。意思是：决不应该～，决不充许～。 前面一般接“ある、許す”等动词。","example":"例：いじめは許すまじき行為だ。","translation":"译文：欺负人是决不能原谅的行为。"},{"point":"～まじき","explain":"だけ的意思是“只、仅”；でなく是ではない的连用形，表示中顿，连用形比て形语气正式。 全意为：不仅～。","example":"例：彼は友達だけでなく、周りのすべての人に信頼されている。","translation":"译文：不仅朋友信赖他，周围所有人都信赖他。"}]},{"category":"不仅～而且","items":[{"point":"～だけでなく","explain":"のみ的意思是“只、仅”，比だけ语气正式；「ならず」是「成らない」的古语形式。 直意为：不成为只是～。 「のみならず」比「だけでなく」语气正式、生硬。","example":"例：この奨学金は日本人の学生のみならず、留学生も応募できる。","translation":"译文：这个奖学金不仅日本学生，留学生也能申请。"},{"point":"～のみならず","explain":"ばかり的意思是“全是、光是、净是”；か表示不确定。 直意为：哪儿光是～。","example":"例：彼は聡明であるばかりか、スポーツも万能だ。","translation":"译文：他哪儿光是聪明啊，就连体育运动都是全能。"},{"point":"～ばかりか","explain":"も的意思是“都、连、也”；さる是「其る」或「然る」，是そう的古语连体形；ながら表示转折。 全意为：～虽然是这样，但是还有～。","example":"例：親の希望もさることながら、子供自身も海外留学に憧れている。","translation":"译文：不仅父母的希望如此，孩子自己也向往着海外留学。"},{"point":"～もさることながら","explain":"に表示方向。 意思是：在～之上，还有～。表示累加。","example":"例：今日は遅刻したうえにテキストも忘れた。","translation":"译文：今天不仅迟到了，还忘了课本。"},{"point":"～上に","explain":"に表示方向；「とどまらず」是「止まらない」的古语形式。 全意为：不停留在～上。","example":"例：火事はふもとにとどまらず、山全体にも及んだ。","translation":"译文：火灾不只是山脚，还遍及了整座山。"},{"point":"～にとどまらず","explain":"名词「如何」如字面所示意思是“如何”；「関わらず」是「関わらない」的古语形式。 全意为：与～的如何无关。","example":"例：社員の意見のいかんにかかわらず、その解決案は可決された。","translation":"译文：与社员的意见如何无关，那个解决方案被通过了。"}]},{"category":"不管，尽管","items":[{"point":"～いかんにかかわらず","explain":"名词「如何」如字面所示意思是“如何”；「よらず」是「由らない」的古语形式。 「由る」的意思是“根据；由于；由～来做～”。 全意为：不根据～的如何。","example":"例：理由のいかんによらず、規則違反は許されない。","translation":"译文：不管什么理由，都不能允许违反规则。"},{"point":"～いかんによらず","explain":"名词「如何」如字面所示意思是“如何”；「問わず」是「問わない」的古语形式。 全意为：不问～的如何。","example":"例：経験のいかんを問わず、この職は誰でも応募できる。","translation":"译文：不管经验如何，这个职位谁都能应聘。"},{"point":"～いかんを問わず","explain":"名词「如何」如字面所示意思是“如何”；「問わず」是「問わない」的古语形式。全意为：不问～的如何。","example":"例：経験のいかんを問わず、この職は誰でも応募できる。 例：いくら説明しても(いくら説明したところで)、彼に誤解されてしまう。 例：どんなに頑張っても(どんなに頑張ったところで)、彼には追いつかないので、悔しい。 例：いかに困難な仕事でも(いかに困難な仕事であれ)、最後までやり抜くつもりだ。 例：たとえ今回の試験に合格しなくても(たとえ今回の試験に合格しなかったところで)、気を落とさないで、引き続き頑張るつもりだ。 例：いくら事情があるからといって、仕事を放り出すことはできないだろう。","translation":"译文：不管经验如何，这个职位谁都能应聘。 いくら～ても(でも/たところで/であれ) どんなに～ても(でも/たところで/であれ) いかに～ても(でも/たところで/であれ) たとえ～ても(でも/たところで/であれ) 「いくら」的意思是：多少次。 「どんなに」的意思是：怎么样地。 「如何に」的意思是：如何地，怎么样地。 以上三者可以互换，いかに语气最正式； 全意为：不管怎么～都～。 「たとえ」是「例える」的连用形，意思是举例、比喻、假设，此处为假设； 全意为：即使假设～也～。 表示“即使、尽管、不管”的有「一ても」和「ーでも」。 「ーても」是动词和形容词的て形后接も构成的。「ーでも」是だ的中顿形式で加も构成的。前面接形容词或名词。 比「ーても」更加正式的是「ーたところで」。是动词和形容词的た形后接表示转折的ところで构成的。 比「ーでも」更加正式的是「ーであれ」。是であつっても的古语形式。 译文：不管怎么译文都被他误解。 译文：不管怎么努力都赶不上他，觉得窝囊。 译文：不管多么艰苦的工作，我都决心要干到底。 译文：即使假设这次考试不及格，我也决心不灰心丧气，继续努力。 いくら～からといって いくら的意思是多少次；から表示原因；「といって」是「と言っても」省略了も。 全意为：不管怎么因为～，也～。 口语中常用いくら～からって。 译文：不管怎么说因为有特殊情况，也不能扔下工作不管吧。"},{"point":"いくら～ても(でも/たところで/であれ)","explain":"","example":"","translation":""},{"point":"どんなに～ても(でも/たところで/であれ)","explain":"","example":"","translation":""},{"point":"いかに～ても(でも/たところで/であれ)","explain":"「いくら」的意思是：多少次。 「どんなに」的意思是：怎么样地。 「如何に」的意思是：如何地，怎么样地。 以上三者可以互换，いかに语气最正式； 全意为：不管怎么～都～。 「たとえ」是「例える」的连用形，意思是举例、比喻、假设，此处为假设； 全意为：即使假设～也～。 表示“即使、尽管、不管”的有「～ても」和「ーでも」。 「ーても」是动词和形容词的て形后接も构成的。「ーでも」是だ的中顿形式で加も构成的。前面接形容词或名词。 比「ーても」更加正式的是「ーたところで」。是动词和形容词的た形后接表示转折的ところで构成的。 比「ーでも」更加正式的是「ーであれ」。是であつっても的古语形式。","example":"例：いくら説明しても(いくら説明したところで)、彼に誤解されてしまう。 例：どんなに頑張っても(どんなに頑張ったところで)、彼には追いつかないので、悔しい。 例：いかに困難な仕事でも(いかに困難な仕事であれ)、最後までやり抜くつもりだ。 例：たとえ今回の試験に合格しなくても(たとえ今回の試験に合格しなかったところで)、気を落とさないで、引き続き頑張るつもりだ。","translation":"译文：不管怎么结果被他误解。 译文：不管怎么努力都赶不上他，觉得窝囊。 译文：不管多么艰苦的工作，我都决心要干到底。 译文：即使假设这次考试不及格，我也决心不灰心丧气，继续努力。"},{"point":"たとえ～ても(でも/たところで/であれ)","explain":"","example":"","translation":""},{"point":"いくら～からといって","explain":"全意为：不管怎么因为～，也～。 口语中常用いくら～からって。","example":"例：いくら事情があるからといって、仕事を放り出すことはできないだろう。","translation":"译文：不管怎么说因为有特殊情况，也不能扔下工作不管吧。"},{"point":"～にしたって","explain":"","example":"","translation":""},{"point":"～にしたって是～にしても","explain":"的口语形式，语气强。在此表示举例。","example":"例：怒るにしたって、あんな大きな声で怒鳴ることはないだろう。","translation":"译文：即使生气，也不用那么大声发脾气吧。"}]},{"category":"不管～还是～","items":[{"point":"～かれ～かれ","explain":"是～にしても的口语形式，语气强。在此表示举例。","example":"例：怒るにしたって、あんな大きな声で怒鳴ることはないだろう。","translation":"译文：即使生气，也不用那么大声发脾气吧。"},{"point":"～かろうと～なかろうと","explain":"接在部分形容词词干后。 意思是：不管～，还是～。","example":"例：気にしないとは言っているが、やはり多かれ少なかれ傷ついた。 例：遅かれ早かれ、いつか終わりが来る。","translation":"译文：说不在乎，可是或多或少还是受到了伤害。 译文：早晚有一天要结束的。"},{"point":"～だろうが～だろうが","explain":"接在形容词词干后，前一个是肯定形，后一个是否定形。有推测的语气。 意思是：不管～，还是～。","example":"例：意見が正しかろうと正しくなかろうと、耳を傾ける必要がある。","translation":"译文：不管意见是正确还是不正确，都需要倾听。"},{"point":"～であろうが～であろうが","explain":"だろう是です的推测形式。「～であろうが」比「～だろうが」语气正式。","example":"例：貧乏だろうがお金持ちだろうが、それは友を選ぶ基準ではない。","translation":"译文：不管对方是穷人还是有钱人，这不是择友的标准。"},{"point":"～ようが～しようが","explain":"あろうが~であろうが だろう是です的推测形式。 「～であろうが」比「～だろうが」语气正式。","example":"例：貧乏だろうがお金持ちだろうが、それは友を選ぶ基準ではない。","translation":"译文：不管对方是穷人还是有钱人，这不是择友的标准。"},{"point":"～ようと～ようと","explain":"が~ようが","example":"例：親が賛成しようが反対しようが、留学する気持ちは変わらない。","translation":"译文：不管父母要赞成还是要反对，我留学的心情是不会改变的。"},{"point":"～ようと～まいと","explain":"~ようと 此处的一よう是动词的意志形。“意志”英语为 will，因此日语的意志形就可以理解为要去做某事。一般动词的意志形后面要加と。 全意为：不管是要～，还是要～； 「ーようがーようが」和「ーようとーようと」这两个句型在意思上和用法上没有区别，只是「ーようがーようが」比「ーようとーようと」的转折语气强。","example":"例：親が賛成しようが反対しようが、留学する気持ちは変わらない。","translation":"译文：不管父母要赞成还是要反对，我留学的心情是不会改变的。"},{"point":"～にしても～にしても","explain":"~まいと 此处的一よう代表动词的意志形。“意志”英语为 will，因此日语的意志形就可以理解为要去做某事。一般动词的意志形后面要加と。 「ーまい」在此处是「しないでしょう」，「ーまいと」是动词意志形的否定形。 全意为：不管要～，还是不要～。","example":"例：仕事しようとしまいと、社会的なルールを学ばなければならない。","translation":"译文：不管工作还是不工作，必须学习社会规则。"},{"point":"～にしろ～にしろ","explain":"~にしても 日语里有一个经典句型搭配就是「～を～に(と)する(把～当成～)」。 ても的意思是“即使、尽管、不管”；に表示对象或目的。 此处是举出两个例子。 前面可以接名词和谓语词(动词、形容词和形容动词)的简体。","example":"例：私が行くにしてもあなたが行くにしても、まず状況をつかんでおく必要がある。","translation":"译文：不管是你去还是我去，有必要事先掌握情况。"},{"point":"～にせよ～にせよ","explain":"しろ~にしろ","example":"例：寒いにしろ暑いにしろ、どうせ遠くまで行かないから大丈夫だ。 例：気に入るにせよ気に入らないにせよ、引き受けた仕事は最後までやりさない。","translation":"译文：不管是冷还是热，反正不去远处，所以没关系。 译文：不管是喜欢还是不喜欢，接受了的工作就只能干到底。"},{"point":"～につけ～につけ","explain":"せよ~にせよ しろ和せよ都是する的命令形，せよ比しろ语气正式；に表示对象或目的。 此处是举出两个例子。 前面可以接名词和谓语词(动词、形容词和形容动词)的简体。","example":"例：寒いにしろ暑いにしろ、どうせ遠くまで行かないから大丈夫だ。 例：気に入るにせよ気に入らないにせよ、引き受けた仕事は最後までやりさない。","translation":"译文：不管是冷还是热，反正不去远处，所以没关系。 译文：不管是喜欢还是不喜欢，接受了的工作就只能干到底。"},{"point":"～といい～といい","explain":"~につけ つけ是「就ける」的连用形；に表示方向或对象。 につけ是举出“就～”或“关于～”事项的两个例子。 前面接名词和谓语词(动词、形容词和形容动词)的简体。 语气正式、生硬。","example":"例：結果は良きにつけ悪しきにつけ、まずやってみるのが何よりだ。","translation":"译文：不管结果是坏还是坏，先试着做比什么都强。"}]},{"category":"不得不","items":[{"point":"～ざるをえない","explain":"いい~といい といい是「と言う」的连用形，と表示内容。 全意为：不管说～，还是说～。","example":"例：生地といい柄といい、文句をつけようのない服だ。","translation":"译文：不管说质地还是说花样，都是件无可挑剔的衣服。"},{"point":"やむを得ず～","explain":"「ざる」是表示否定的ない的古语连体形；「得ない」的意思是“不得”。 全意为：不得不。 ざる前的动词变为未然形，する要変为せ。 やむを得ず~ 「やむ」的汉字是「已む」；「得ず」是「得ない」的古语形式。 全意为：不得已。","example":"例：経験を積むためなら、好きでもない実習に参加せざるをえない。 例：嵐のため、やむを得ず引き返した。","translation":"译文：假设是为了积累经验，即使是不喜欢的实习也不得不参加。 译文：由于暴风雨，不得已只好返回了。"},{"point":"～を余儀なくされる/～を余儀なくさせる","explain":"「余儀なく」是副词，意思是没有其他办法。 される是する的被动形。前面的主语后接は。 させる是する的使役形。前面的对象后接に。 全意为：不得不～。","example":"例：不況のため社員は賃金カットを余儀なくされた。 例：不意に起こった雪崩は、私たちに登山の計画の中止を余儀なくさせた。","translation":"译文：由于不景气，公司职员被迫被减了工资。 译文：意料之外发生的雪崩让我们被迫中止了登山计划。"}]},{"category":"不顾，顾忌到","items":[{"point":"～てまえ","explain":"「手前」的意思为眼前或周围。 意思是：考虑到或顾忌到周围的事情。","example":"例：みんなの前でやると言ってしまってまえ、今更やらないとは言いにくい。","translation":"译文：顾忌到在大家面前说过要做了，事到如今很难说不做了。"},{"point":"～を尝して","explain":"を的意思是“把”，接在他动词前的助词；「おして」是动词「推す」的中顿形式。 意思是：把～推到一边。","example":"例：彼は親の反対をおして愛する人と結婚した。","translation":"译文：他不顾父母的反对，和他心爱的人结婚了。"},{"point":"～を顧みず","explain":"を的意思是“把”，接在他动词前的助词；「顧みず」是「顧みる」的否定形。 意思是：把～置为不顾。","example":"例：カメラマンは自分の命を顧みず戦場に赴いた。","translation":"译文：摄影记者不顾自己的性命，奔赴战场。"},{"point":"～を問わず","explain":"を的意思是“把”，接在他动词前的助词；「問わず」是「問う」的否定。 常跟「学歴、男女、性別、国籍、経験の有無」等汉语词一起用。 意思是：不问～。","example":"例：この奨学金は国籍を問わず誰でも応募できる。","translation":"译文：不管是什么国籍的学生都能申请这个奖学金。"},{"point":"～をものともせずに","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 も的意思是“都”；もの的意思是“东西或事情”；せず是しない的古语形式；に表示副词。 意思是：都不把～当回事。","example":"例：彼は度重なる困難をものともせずに自分の目標に向かい続けている。","translation":"译文：他不顾重重困难，一直在朝着自己的目标前进。"},{"point":"～をよそに","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 よその汉字为「他所、余所」，意思是其他的地方。 全意为：把～放在别处。","example":"例：親の期待をよそに、子供はゲームに熱中しているだけだ。","translation":"译文：孩子置父母的期待于不顾，只是热衷于游戏。"}]},{"category":"不管怎么说","items":[{"point":"なにしろ～から","explain":"「何」的意思是“什么”，しろ是する的命令语。 意思是：不管怎么说。 さすがに~だけあって さすがに意思是“不愧”；だけ在此表示“相应或符合”，可以把它看作是“二”；あって的意思是“有”。 全意为：不愧是～。","example":"例：なにしろ親友だから、どんな決定を出しても反対しないよ。 例：さすがに有名な学校だけあって、教育器具は何でも揃っている。","translation":"译文：不管怎么说你都是我的好朋友，不管你作出什么决定我都不会反对的。 译文：不愧是有名的学校，教育器械非常齐全。"}]},{"category":"不愧是","items":[{"point":"さすがに～だけあって","explain":"やまない是「止む」的否定形。 前面常用「期待する、祝う、祈る、願う、祝福する」等动词。 思わず~てしまう 「思わず」的意思是“禁不住、不由得、无意识地”；「～てしまう」表示做完某事，有无可挽回的语气。 つい~てしまう 和「思わず～てしまう」在意思上、使用方法上和语气上均相同。 注：もがな的も可以理解为～ても；が可以理解为接续助词，在此处无具体意思；な的意思是いいなあ。全意为：要是～该有多好啊。","example":"例：皆様の今後のご活躍を心より祈ってやみません。 例：あまりにも嬉しかったから、思わず飛び上がってしまった。 例：あまりにも頭に来たので、つい言わずもがなのことを言ってしまった。","translation":"译文：我从心里不停地祝愿大家今后事业有成。 译文：因为太高兴了，不由得跳了起来。 译文：太生气了，不由得说了不该说的话。"}]},{"category":"不停地","items":[{"point":"～てやまない","explain":"他动词「禁じる」接「得ない」构成复合动词；「ー得ない」的意思是不可能。を是接在他动词前的助词。 全意是：禁不住～。","example":"例：彼の傲慢な振る舞いには怒りを禁じえない。","translation":"译文：对于他的那种不可一世的举止禁不住愤怒。"}]},{"category":"不由得","items":[{"point":"思わず～てしまう","explain":"言うに及ばない は是を的强调；「言う」的意思是“说”；に是表示对象或方向，后面的是强调；「及ばない」的意思是“不及～、不到～的地步”。 全意是：不用说～。","example":"例：夏休み中、山や海は言うに及ばず、市内の遊園地まで親子連れで溢れている。","translation":"译文：暑假中，不用说是山上还是海边，就连市内的游乐园到处都是带孩子来玩儿的一家人。"},{"point":"～を禁じえない","explain":"は是を的强调；おろか的汉字是「疎か」，相对应的中文的汉字是疏远的疏。 直译为：把～放在远的地方。意译为：不用说～。","example":"例：日本に来た最初のころは、漢字の読み方はおろか、仮名も読めなかった。","translation":"译文：刚来日本的时候，别说汉字的读音了，连假名也不会念。"}]},{"category":"不用说","items":[{"point":"～は言うには及ばない","explain":"は是を的强调；ともかく的意思是“姑且不论、暂且不谈”。","example":"例：良し悪しはともかく、事実は事実だよ。","translation":"译文：先不说是好是坏，事实就是事实。"},{"point":"～はおろか","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 「別」的意思是“其他的事情”。 全意为：把～放在别处不考虑。","example":"例：会話は別にして、まず仮名の読み書きをきちんと覚えるべきだ。","translation":"译文：先不提会话，首先应该好好记住假名的读写。"},{"point":"～はともかく","explain":"は是接在大主语后面的助词；もちろん的意思是“当然”。 意思是：～当然如此，此外还有～。 后面的句子要用表示“也”的「も、まで、までも」。这三个词一个比一个语气强。","example":"例：日本の地名や人名の読み方は、外国人にはもちろん、日本人にもかなり難しい。","translation":"译文：日本的地名和人名的念法，不用说对于外国人，对日本人也相当难。"},{"point":"～は別にして","explain":"は是接在大主语后面的助词；「もと」的汉字是「元、本」等；より和表示“从”的から意思相同。 全意为：从原来开始就～，那现在就不用说了。 比～はもちろん语气更加正式、生硬。","example":"例：学生はもとより、先生までこの難問に首を傾げた。","translation":"译文：别说学生了，连老师都对这道难题感到头疼。"},{"point":"～はもちろん","explain":"助词も接在数量词后，一般强调数量多。","example":"例：餃子は20個も食べた。 例：あの映画は何回も見た。","translation":"译文：吃了 20 个饺子。 译文：看了好几遍那部电影。"},{"point":"～はもとより","explain":"は是接在大主语后面的助词；「もと」的汉字是「元、本」等；より和表示“从”的から意思相同。全意为：从原来开始就～，那现在就不用说了。比～はもちろん语气更加正式、生硬。","example":"例：学生はもとより、先生までこの難問に首を傾げた。 例：もう少しで転びそうになった。 例：もう少しで乗り過ごすところだった。","translation":"译文：别说学生了，连老师都对这道难题感到头疼。 C 差点儿就 もう少しで~そうになる もう的意思是“再”；すこし是“一点儿”；で表示程度；动词连用形加「そうになる」的意思是“成为好像～”。 直意为：差一点儿就要成为～的好像了。 着重样子和状态。 译文：差一点儿就摔了一个跟头。 もう少しで~ところだった もう的意思是“再”；すこし是“一点儿”；で表示程度；ところ在此处的意思是“时间”；だった是です过去式。 要接动词的一般现在时，主要表示将来。 直意为：过去是将要做～的时候。 着重时间。 译文：差点儿就坐过站了。"},{"point":"~は言うに及ばない","explain":"は是を的强调；「言う」的意思是“说”；に是表示对象或方向，后面的是强调；「及ばない」的意思是“不及～、不到～的地步”。全意是：不用说～。","example":"例：夏休み中、山や海は言うに及ばず、市内の遊園地まで親子連れで溢れている。","translation":"译文：暑假中，不用说是山上还是海边，就连市内的游乐园到处都是带孩子来玩儿的一家人。"}]},{"category":"差点儿就","items":[{"point":"もう少しで～そうになる","explain":"から是“从～开始”，有在此之上的意思；ある的意思是有，后面修饰名词。 のは为了接续名词使用。 二者强调数量多，语气也比も正式。","example":"例：彼は1億円からある遺産を相続した。 例：目の前に身長が2メートルからの大男が急に現れた。","translation":"译文：他继承了一亿日元的财产。 译文：眼前突然出现了一个身高两米的大个子男人。"},{"point":"もう少しで～ところだった","explain":"「きれない」是「切る」的可能形的否定。 形容动作多得无法中断。 前接动词连用形。","example":"例：こんなにたくさん注文したら食べきれない。","translation":"译文：点这么多菜可吃不了。"}]},{"category":"程度，数量","items":[{"point":"～も","explain":"助词も接在数量词后，一般强调数量多。","example":"例：餃子は20個も食べた。 例：あの映画は何回も見た。","translation":"译文：吃了20个饺子。 译文：看了好几遍那部电影。"},{"point":"～からある","explain":"表示多、中、少三个数量段。 表示数量多时，一般以「これだけ、それだけ、あれだけ」这三个副词来表示，需要通过上下文来判断其意。 表示数量中时，意思是“相应或符合”，可以理解为“二”。 表示数量少时使用较广。","example":"例：あれだけ残業をしていれば、給料をもっと上げてくれるはずなのに。 例：トップランキングの大学の大学院に受かるだけの学力をつけるむずかのは難しい。 例：この商品は冬にだけ発売される。","translation":"译文：加了那么多班，应该多给我们涨些工资啊。 译文：能够具备考上名牌的大学的研究生院的能力是件困难的事情。 译文：这种商品只在冬天销售。"},{"point":"～からの","explain":"たり是「とあり」的音变，と表示内容，あり的意思是“有”。 とも和ても一样表示转折，意思是“即使、尽管、不管”。 全意为：即使是～也～。 形容数量少，一般有数量词“1”。","example":"例：米は一粒たりとも無駄にできない。","translation":"译文：一粒米都不能浪费。"},{"point":"～きれない","explain":"「きれない」是「切る」的可能形的否定。形容动作多得无法中断。前接动词连用形。","example":"例：こんなにたくさん注文したら食べきれない。","translation":"译文：点这么多菜可吃不了。"},{"point":"～だけ","explain":"ところ的意思为“时间、地点、程度、状况”等，此处表示程度。 形容程度低或数量少。 という的用法是：句子十という十名词。","example":"例：それは単なる遊びといったところだよ。 例：学会のシンポジウムの参加者は千人といったところだった。","translation":"译文：那只不过是一场游戏。 译文：学会专题讨论会的参加者只有一千人。"},{"point":"～たりとも","explain":"表示“高、中、低”三个程度。 程度高 程度中。有“左右”的意思。 程度低。 くらい还可以表示时间和期间，意思为左右。","example":"例：周りが騒がしいから、電話の音が聞こえないくらいだ。 例：歩いて行けるくらい近いです。 例：こんな事くらい子供でも知っている。 例：明日の午後三時くらいに来てください。 例：昨日友達に三時間くらい待たされた。","translation":"译文：周围太吵了，电话的声音都快听不见了。 译文：很近，可以走着去。 译文：这样的事连小孩都知道。 译文：请明天下午 3 点左右来。 译文：昨天朋友让我等了 3 个多小时。"},{"point":"～といったところだ","explain":"表示程度高。 与表示程度高时的くらい没有什么区别。 ほど还可以表示期间，意思为左右，与表示期间时的くらい没有什么区别。 但是不能表示时间点。","example":"例：舌がとろけるほどおいしい。 例：講義は1時間ほど延びた。","translation":"译文：好吃得舌头都要融化了。 译文：课拖延了一个小时左右。"},{"point":"～というところだ","explain":"加在名词的后面表示“从～”。","example":"例：田中さんから得た情報は確実だ。","translation":"译文：从田中那儿得到的信息很准确。"},{"point":"～だけ","explain":"表示多、中、少三个数量段。表示数量多时，一般以「これだけ、それだけ、あれだけ」这三个副词来表示，需要通过上下文来判断其意。","example":"例：あれだけ残業をしていれば、給料をもっと上げてくれるはずなのに。 例：トップランキングの大学の大学院に受かるだけの学力をつけるむずかのは難しい。 例：この商品は冬にだけ発売される。","translation":"译文：加了那么多班，应该多给我们涨些工资啊。 表示数量中时，意思是“相应或符合”，可以理解为“二”。 译文：能够具备考上名牌的大学的研究生院的能力是件困难的事情。 表示数量少时使用较广。 译文：这种商品只在冬天销售。"}]},{"category":"程度","items":[{"point":"～ぐらい","explain":"","example":"","translation":""},{"point":"～ほど","explain":"から加在名词的后面表示“从～”；いう是「言う」；と的意思是“如果”。 在「～と、～ば、～たら、～なら」里，と的条件性最强，なら的假定性最强。","example":"例：実力からいうと(からいえば)、彼が入賞することは間違いない。","translation":"译文：从实力来看，他肯定能得奖。"},{"point":"~くらい","explain":"表示“高、中、低”三个程度。程度高","example":"例：周りが騒がしいから、電話の音が聞こえないくらいだ。 例：歩いて行けるくらい近いです。 例：こんな事くらい子供でも知っている。 例：明日の午後三時くらいに来てください。 例：昨日友達に三時間くらい待たされた。","translation":"译文：周围太吵了，电话的声音都快听不见了。 程度中。有“左右”的意思。 译文：很近，可以走着去。 程度低。 译文：这样的事连小孩都知道。 くらい还可以表示时间和期间，意思为左右。 译文：请明天下午 3 点左右来。 译文：昨天朋友让我等了 3 个多小时。"}]},{"category":"从","items":[{"point":"～から","explain":"から加在名词的后面表示“从～”；して是能够代替所有动词的「する」的中顿，在此代替了「見る、判断する」等词。","example":"例：町並みからしてこのところは歴史のある町らしい。","translation":"译文：从街道的样子来看，这个地方好像历史很悠久。"},{"point":"～からいうと","explain":"~まで 意思为：从～到～。","example":"例：部屋の隅から隅まで探した。","translation":"译文：找遍了房间的各个角落。"},{"point":"～からいえば","explain":"~にいたるまで 「至る」的意思是“到”；此语法比「～から～まで」强调“到”。","example":"例：家事から育児にいたるまで、一人でさせられている。","translation":"译文：从家务活到抚养孩子都不得不一个人干。"},{"point":"～からして","explain":"~にかけて 「～から～まで」使用范围较广，而「～から～にかけて」只用于时间不能用于地点等，语气正式、生硬。","example":"例：日本は5月の下旬から6月の下旬にかけて梅雨の時期だ。","translation":"译文：日本从 5 月下旬到 6 月下旬是梅雨季节。"},{"point":"～から～まで","explain":"接在人称后表示“从”，比から语气正式，一般写信或表示送东西的赠送人时用得较多。","example":"例：田中様より鈴木様宛ての手紙がお預かりしております。","translation":"译文：田中给铃木的信放在我们这里。"},{"point":"～から～にいるまで","explain":"他动词「込める」的意思为装满或充满。を是接在他动词后的助词。 常用「心をこめて、愛情をこめて」。 除了~以外","example":"例：これはわたしが真心をこめて言った言葉です。 例：先生は毎回愛情をこめて授業を行っている。","translation":"译文：这是我真心实意说的话。 译文：老师的每堂课都充满了对学生的爱。"},{"point":"～から～にかけて","explain":"名词「他」的意思是“其他”。に表示副词。 有时可以不用に，不用に时语气正式。 意思为：～之外，以外。","example":"例：当日は関係書類が配られるほか、記念品ももらえる。","translation":"译文：当天除了发有关资料以外，还能得到纪念品。"},{"point":"～より","explain":"名词「以外」后面加に变为副词。","example":"例：彼女は声が大きい以外に何の取得もない。","translation":"译文：她除了声音大以外什么可取之处都没有。"},{"point":"~から~にいたるまで","explain":"「至る」的意思是“到”；此语法比「～から～まで」强调“到”。","example":"例：家事から育児にいたるまで、一人でさせられている。","translation":"译文：从家务活到抚养孩子都不得不一个人干。"}]},{"category":"充满","items":[{"point":"～をこめて","explain":"他动词「除く」的意思是“除了～”。","example":"例：少数を除いてみんなその提案に賛成した。","translation":"译文：除了少数人，大家都赞同了那个建议。"}]},{"category":"除了～以外","items":[{"point":"～ほかに","explain":"他动词「置く」的意思是“把～放到一边”，意译为：除了～。を是接在他动词后的助词。","example":"例：この仕事が任せられるのは、彼をおいて適任者はいない。","translation":"译文：这个工作除了他以外没有别人可以胜任。"},{"point":"～以外に","explain":"名词「代わり」后面加に变为副词。","example":"例：包帯のかわりに、ハンカチで傷口を縛った。","translation":"译文：用手绢代替绷带绑住了伤口。"},{"point":"～を除いて","explain":"「かわって」是动词「代わる」的中顿；に表示对象。","example":"例：首相にかわって、外相が米国を訪問した。","translation":"译文：外相代替首相访问了美国。"},{"point":"～をおいて","explain":"他动词「置く」的意思是“把～放到一边”，意译为：除了～。を是接在他动词后的助词。","example":"例：この仕事が任せられるのは、彼をおいて適任者はいない。","translation":"译文：这个工作除了他以外没有别人可以胜任。 D"}]},{"category":"代替","items":[{"point":"～かわりに","explain":"日语里的一个经典句型，大多数语法都是此句型的派生。 を的意思是“把”，する可以替代任何一个动词；に和との区别在于に着重方向或对象，と着重于内容。 意思为：把～当成～。 到~地步","example":"例：経済を研究題目にしている。","translation":"译文：现在把经济当作研究题目。"},{"point":"～にかわって","explain":"まで的意思是“到～的地步”。 可以接在任何一 个词后面。","example":"例：今年の大学の文化祭は以前ほど活気がなくなった。授業を休んでまで見に行く必要はないと思う。","translation":"译文：今年大学的文化节没有以前有生气，我觉得没有必要不上课去观看。"}]},{"category":"当成","items":[{"point":"～を～とする","explain":"までも比まで语气强。 意思为：不用到去做～的地步，但是～也该做。","example":"例：新しい建設計画には地元の住民の反対が大きい。国は計画を中止するとは言わないまでも、もう一度考え直さざるを得ないだろう。","translation":"译文：当地居民非常反对新的建设计划。国家即使不说中止计划，也不得不重新考虑吧。"},{"point":"～を～にする","explain":"に表示方向；「至って」是动词「至る」的中顿。","example":"例：事ここに至っては手の打ちようがない。","translation":"译文：事已至此，一点儿办法都没了。"}]},{"category":"到～地步","items":[{"point":"～まで","explain":"と表示内容，在此起到引号的作用；は表示强调；句尾常接可以代替多数名词的こと十だ，与主语的名词相呼应。","example":"例：「アクセサリー」とは、体につける飾りのことだ。","translation":"译文：首饰的意思是戴在身上的装饰品。"},{"point":"～ないまでも","explain":"「きり」是动词「切る」的连用形；前面的动词为过去式。 意思为：做完了～之后动作中断，之后再也没有做过此事。","example":"例：渡辺先生とは昨年一度会ったきりです。 例：祖父は階段から転んでから、ずっと寝たきりだ。","translation":"译文：去年和渡边老师见过一面后再也没见过。 译文：祖父从台阶上摔下来后一直卧床不起。"},{"point":"～に至って","explain":"は在两个小句子当中表示对比。 此外，は还有接在大主语后；强调其他助词的作用。 强调を和が时，去掉二者换成は；强调其他助词如に、で等时，后面加は，构成「には、では」等。","example":"例：日本に来て初めのうちは日本語が全然わからなかったけど、今はだいぶわかってきた。","translation":"译文：刚来日本的时候日语一点儿也不懂，现在懂很多了。"}]},{"category":"定义","items":[{"point":"～とは","explain":"意思是“一方面～，另一方面～”。 常举出两个对照性的事物。 前面接动词简体。有时在「一方」后面可以加上です的中顿で，不用で时语气正式。","example":"例：最近高齢化が進んでおり、老人は増える一方(で)、子供の数は減ってきている。","translation":"译文：最近高龄化越发严重，老人在增加，另一方面孩子的数量在减少。"}]},{"category":"动作的终结","items":[{"point":"～たきり","explain":"意思有两个：一个是“对于～”，另一个意思是“与～相对比”。に表示对象。 前面接名词。","example":"例：光に当ている面の色が濃いのに対して、当ていない面の色は薄い。","translation":"译文：光照的一面的颜色深，与其相对照，没有光照的一面的颜色淡。"}]},{"category":"对比","items":[{"point":"～は","explain":"「引き替える」的意思是“交换”；に表示对象。 前面接名词。","example":"例：先月日用品の売り上げが著しく伸びたのにひきかえ、食料品の売り上げは落ち込んだ。","translation":"译文：上月日用品的销售额有显著的增长，与此相反，食品的销售额下降了。"},{"point":"～に対して","explain":"「～っぱなし」是动词「放す」的连用形，作名词用；促音是加强语气。 全意为：放置不管。 有消极语气。","example":"例：主人は家事を一切しない。新聞は広げっぱなしにしているし、脱いだ上着もソファーに置きっぱなしにしている。まったく、あきれたよ。","translation":"译文：我丈夫家务事儿一点儿都不干。报纸摊开着，脱掉的外套也扔在沙发上不管。简直服了。"},{"point":"～にひきかえ","explain":"「あまり」是动词「余る」的连用形，作名词用。 意思为：过于～。","example":"例：志望大学に受かって、嬉しいあまり、泣いてしまった。","translation":"译文：考上了想要的大学，过于高兴结果哭了。"},{"point":"~一方","explain":"意思是“一方面～，另一方面～”。常举出两个对照性的事物。前面接动词简体。有时在「一方」后面可以加上です的中顿で，不用で时语气正式。","example":"例：最近高齢化が進んでおり、老人は増える一方(で)、子供の数は減ってきている。","translation":"译文：最近高龄化越发严重，老人在增加，另一方面孩子的数量在减少。"}]},{"category":"放置不管","items":[{"point":"～っぱなし","explain":"「至り」是动词「至る」的连用形，作名词用；で是です的中顿。 意思为：～之至。","example":"例：若気の至りで、生意気なことを言ってしまい、申し訳ございません。","translation":"译文：太幼稚了，出言不逊，非常抱歉。"}]},{"category":"非常，极其","items":[{"point":"～あまり","explain":"「限り」是动词「限る」的连用形，作名词用。 意思为：极限、极其。","example":"例：この度、皆様のお世話をさせていただきまして、光栄の限りです。","translation":"译文：此次能够负责照顾大家，非常荣幸。"},{"point":"～の至りで","explain":"名词「極み」的意思是“极限”。 前面要接名词。 语气正式、生硬。","example":"例：遠いところからわざわざお越しいただきまして、恐縮の極みでございます。","translation":"译文：您特地远道而来，非常过意不去。"},{"point":"～限りだ","explain":"「極まり」是动词「極まる」的名词形式，意思是“极限”；ない的意思是“没有”。 全意为：没有比～更～的了。 前面要接形容词。","example":"例：信号を無視して突っ走るなんて、危険きわまりない。","translation":"译文：不看红绿灯猛跑太危险了。"},{"point":"～のきわみ","explain":"表示极限的动词「極まる」前面直接形容词，后面修饰名词。 全意为：没有比～更～的了。","example":"例：彼の無礼きわまる態度に腹が立った。","translation":"译文：对他的极其无礼的态度非常生气。"},{"point":"～きわまりない","explain":"と表示内容；いったら的原形是「言う」，たら的意思是“如果”；あり是「有る」的连用形，作名词用；しない是能代替任何动词的する的否定形。 口语中还常用「～といったらありゃしない」「～といったらない」。 全意为：简直太～。","example":"例：二時間も待たされて、けしからんといったらありゃしない。","translation":"译文：让我等了两个小时，简直太不像话了。"},{"point":"～きわまる","explain":"は、~ては 用动词的て形表示中顿；は是强调。 后接动词的连用形作为名词，所以最后面要加动词。","example":"例：休みの日はいつも食べては寝、食べては寝している。","translation":"译文：休息日总是吃了睡，睡了吃。"},{"point":"～といったらありはしない","explain":"と表示内容；いったら的原形是「言う」，たら的意思是“如果”；あり是「有る」的连用形，作名词用；しない是能代替任何动词的する的否定形。口语中还常用「～といったらありゃしない」「～といったらない」。全意为：简直太～。","example":"例：二時間も待たされて、けしからんといったらありゃしない。","translation":"译文：让我等了两个小时，简直太不像话了。"}]},{"category":"反复做","items":[{"point":"～ては～ては","explain":"的汉字为「方」。 前接动词的连用形构成复合名词。","example":"例：いくら後悔したって、もう仕方がない。","translation":"译文：不管怎么后悔都没办法了。"},{"point":"~ては、~ては","explain":"用动词的て形表示中顿；は是强调。后接动词的连用形作为名词，所以最后面要加动词。","example":"例：休みの日はいつも食べては寝、食べては寝している。","translation":"译文：休息日总是吃了睡，睡了吃。"}]},{"category":"方法","items":[{"point":"～かた","explain":"","example":"","translation":""},{"point":"～よう","explain":"的汉字为「様」。 前接动词的连用形构成复合名词。 比~かた语气稍生硬。","example":"例：本のタイトルさえわかれば、探しようがあるけど…","translation":"译文：只要知道书的名字就有办法找。"},{"point":"～を以て","explain":"意思是“以～的方法”，还可以表示“以～为开始或结束的界限点”，","example":"例：18時を以て終了します(18点结束)。 例：審査の結果は書面を以てお知らせいたします。","translation":"译文：审查的结果以书面形式通知。"},{"point":"~かた","explain":"的汉字为「方」。前接动词的连用形构成复合名词。","example":"例：いくら後悔したって、もう仕方がない。","translation":"译文：不管怎么后悔都没办法了。"},{"point":"~よう","explain":"的汉字为「様」。前接动词的连用形构成复合名词。比~かた语气稍生硬。","example":"例：本のタイトルさえわかれば、探しようがあるけど…","translation":"译文：只要知道书的名字就有办法找。"}]},{"category":"方面","items":[{"point":"～上で","explain":"で表示范围。 意思为：在～方面上。 前面用动词的一般现在时来表示一般性的状况。","example":"例：適当な運動をするのは、健康と美容を保つ上で大切な一環だと見られる。","translation":"译文：适当的运动在保持健康和美容方面被看作是重要的一环。"},{"point":"～点で","explain":"で表示范围。 意思为：在～点上。","example":"例：あの二人はせっかちだという点では共通している。","translation":"译文：那两个人性格急。"},{"point":"～にかけては","explain":"かける意为“大面积的覆盖”；に表示方向；は表示强调。 意思是：在～方面。","example":"例：彼は経営にかけては優れた才能を発揮している。","translation":"译文：他在经营方面发挥着杰出的才能。"}]},{"category":"符合","items":[{"point":"～だけ","explain":"表示相应或符合，可以理解为“二”。","example":"例：くたびれて、お風呂に入るだけの元気も出ない。","translation":"译文：累死了，连洗澡的力气都没有了。"},{"point":"～だけあって","explain":"だけ在此处是相应或符合，可以理解为“二”；あって的意思是“有”。 常与さすがに相接，意思是“不愧”。","example":"例：さすがに専門家だけあって、見方が鋭いね。","translation":"译文：不愧是专家，看法真敏锐。"},{"point":"～たる","explain":"「たる」是「とある」的音变。 前后接名词，可以理解为“二”。 语气正式。","example":"例：教師たる者は、常に知識を追求しなければならない。","translation":"译文：作为教师不经常追求知识是不行的。"},{"point":"～なり","explain":"「なり」是表示成为的「なる」的连用形，作名词用。 后面接名词时加の；后面接动词时加に变副词。 意思为：按照～自身的方式。","example":"例：私は自分なりの考えを申し上げただけです。 例：子供は子供なりに自分の世界を持っている。","translation":"译文：我只不过陈述了我自己的想法。 译文：孩子们拥有自己的世界。"}]},{"category":"感叹","items":[{"point":"なんと～","explain":"なん的意思是“什么”；と表示说的内容；なんとの意思是：说什么好呢？ 全意是：多么～啊。","example":"例：モノレールができるから、なんと便利になるのかわからない。 例：なんと綺麗な人。","translation":"译文：要建单轨电车了，不知道会变得多么方便啊。 译文：这个人太漂亮了。"},{"point":"どんなに～だろう","explain":"","example":"","translation":""}]},{"category":"刚～","items":[{"point":"～かける","explain":"意思是：多么～啊。","example":"例：日本語がべらべらに話せるようになったら、どんなに楽しいことだろう。","translation":"译文：如果能流利地说日语了，该是多么高兴的事啊。"}]},{"category":"根据，按照","items":[{"point":"～をもとに","explain":"前面接动词的连用形变为复合动词。 意思为：开始了某事但是没完，还在过程当中。","example":"例：このおかずは腐りかけている。 例：食卓には食べかけのパンが置いてある。","translation":"译文：这盘菜要坏了。 译文：饭桌上放着没吃完的面包。"},{"point":"～に基づいて","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 「もと」的汉字为「元、本」等。 全意为：以～为根本。","example":"例：このドラマは事実をもとに作られたものだ。","translation":"译文：这个电视剧是根据事实创作的。"},{"point":"～を踏まえて","explain":"「基づく」是「もと＋付く」的组合，意思是“附着在根本上”；に表示方向。 全意为：基于～。","example":"例：彼の助言は長年の経験に基づいて出されたものだから、納得できる。","translation":"译文：他的指教是基于长年的经验，可以心服口服。"},{"point":"～に応じて","explain":"他动词「踏まえる」的意思是“踏着～”。を是接在他动词前的助词。 着重于“根本和步骤”两方面。","example":"例：昨年の反省を踏まえて、今後の計画を立てたい。","translation":"译文：我们想根据去年的反省制定今后的计划。"},{"point":"～によって","explain":"「応じる」的意思是“相应，对应”；に表示对象。 原意是：与～相对应。","example":"例：実際の収入に応じて、支出を考えなければいけない。","translation":"译文：必须根据实际收入考虑支出。"},{"point":"～通り","explain":"「よって」是「由る」的中顿；に表示“方向，对象”。 有“根据、由于、由～来做”三个意思。","example":"例：中国語の多音字は、アクセントの違いによって意味も変わるというものだ。","translation":"译文：汉语的多音字根据声调的不同意思也不同。"},{"point":"～にこたえて","explain":"「通り」的原意是“马路”；如果变副词则加に。 着重于“顺序或步骤”。","example":"例：先生のおっしゃる通りです。 例：説明書の通りに操作してください。","translation":"译文：老师您说得很对。 译文：请按照说明书操作。"},{"point":"～に即して","explain":"「答える」的意思是“回答”；に表示方向或对象。 着重于回答问题或提议等。 前面常接「声、要望、希望」等词。","example":"例：学生の声にこたえて教え方を変えた。","translation":"译文：根据学生的要求改变了教学方法。"},{"point":"～なりに","explain":"「即する」是从「即応する」演变而来，意思是“与～相对应”；に表示方向或对象。 着重于百分之百一样。 语气正式、生硬。","example":"例：実情に即して対応策を検討したい。","translation":"译文：我们想根据实际情况研究对策。"},{"point":"～に沿って","explain":"「なり」是表示成为的「なる」的连用形，作名词使用；に是变名词为副词。 意思为：按照～自身的方式，也可以理解为符合～。","example":"例：わたしはわたしなりに生きていきたい。","translation":"译文：我想按照自己的方式生活。"},{"point":"～次第","explain":"「次」的意思是“下一个”，「第」在此处可以理解为“第二个”。前面接名词，构成符合名词。意思为：根据～下一步马上就～。","example":"例：条件次第では売らないことはない。","translation":"译文：根据条件如何，有可能卖掉。"}]},{"category":"关于，对于","items":[{"point":"～に関して","explain":"「次」的意思是“下一个”，「第」在此处可以理解为“第二个”。 前面接名词，构成符合名词。 意思为：根据～下一步马上就～。","example":"例：条件次第では売らないことはない。","translation":"译文：根据条件如何，有可能卖掉。"},{"point":"～にかかわる","explain":"「沿う」的意思是“沿着”；に表示方向。 由于原意是沿着某条路线行走，所以着重于步骤。 一般是沿着方针或路线等。","example":"例：容器リサイクル法は、地域の実情に沿って行わなければならない。","translation":"译文：容器再利用法必须按照各个地区的实际情况实施。"},{"point":"～に対して","explain":"「関して」是「関する」的中顿，意思是“有关系”；に表示对象。 全意为：关于～。","example":"例：外国の言葉を習う時、その国の文化や習慣に関しても知ったほうがいい。","translation":"译文：学外语的时候，最好知道那个国家的文化和习惯。"},{"point":"～に向かって","explain":"「関わる」的意思是“有关系”；に表示对象。 全意为：关于～。 语气正式、生硬。","example":"例：これは名誉にかかわる問題だから、誰だって真剣になる。","translation":"译文：这是有关名誉的问题，谁都会认真。"},{"point":"～にとって","explain":"「対して」是「対する」的中顿；に表示对象。 意思是：对于～。 除此意思之外还有对比的意思。","example":"例：サービス業なので、お客さんに対して失礼な態度を取ってはいけない。","translation":"译文：因为是服务行业，对客人采取失礼的态度不行。"},{"point":"～について","explain":"「向かって」是「向かう」的中顿，意思是“朝向”；に表示“方向、对象、目的、目标”。","example":"例：東に向かってまっすぐ行ってください。 例：先生に向かって何ってことを言うの？ 例：オリンピックに向かってみんなで頑張りましょう。","translation":"译文：请朝东一直走。 译文：你怎么这么对老师说话？ 译文：大家朝着奥林匹克一起加油吧。"},{"point":"～をめぐって","explain":"に表示对象。 意思是：对～来说。","example":"例：環境保護はすべての人にとって意識に昇らなくてはならない重要な課題だ。","translation":"译文：对于所有人来说，保护环境是必须上升到意识的重要课题。"}]},{"category":"关于済む","items":[{"point":"～で済む","explain":"「ついて」是「就く」的中顿；に表示对象。 意思是：就～进行～。","example":"例：わが社の新製品についてご紹介します。","translation":"译文：我来介绍一下我们公司的新产品。"},{"point":"～では済まない","explain":"自动词「巡る」的意思是“围绕”；を接在自动词前表示移动。 意思是：围绕着～的话题。","example":"例：新しい法案の実施の賛否をめぐって、活発な議論が交わされた。","translation":"译文：围绕着是否赞成新法案的实施展开了活跃的讨论。"},{"point":"～ずに済む","explain":"「済む」的意思是“事情终了、结束”；で表示程度。 全意为：以～的程度，事情结束了或解决了。 着重于程度低。","example":"例：今日の昼ごはんはお弁当を頼んだから400円で済んだ。","translation":"译文：今天的午饭订了盒饭，只花了400日元。"},{"point":"～ずには済まない","explain":"「済む」的意思是“事情终了、结束”；で表示程度；は表示强调。 全意为：以～的程度，事情就不会结束或不会解决。","example":"例：これは謝るだけでは済まないことだよ。","translation":"译文：这可不是光道个歉就能解决的事。"}]},{"category":"关于いる","items":[{"point":"～ていられる","explain":"「済む」的意思是“事情终了、结束”；ず是否定ない；に表示副词。 此处可以把「ずに」换成「ないで」， 「ずに」比「ないで」语气正式。 全意为：不做～，事情就结束了或解决了。","example":"例：言いたいことは全部言ってくれたから、何も言わずに済んだ。","translation":"译文：想说的话你都替我说了，我什么都不用说了。"},{"point":"～てはいられない","explain":"「済む」的意思是“事情终了、结束”；ず是否定ない；に表示副词，は表示强调。 此处可以把「ずに」换成「ないで」， 「ずに」比「ないで」语气正式。 全意为：不做～，事情就不会结束或不会解决。","example":"例：高価なものを壊したから、弁償せずにはすまないだろう。","translation":"译文：把贵重的东西弄坏了，不赔偿事情完不了吧。"},{"point":"～ずにいられる","explain":"「ーていられる」是动词的现在进行时「ーている」的可能形。 意思是：能够保持～的状态。","example":"例：親と一緒に暮らせば安心していられる。","translation":"译文：跟父母在一起生活的话就心里踏实。"},{"point":"～ずにはいられない","explain":"「ーてはいられない」是动词的现在进行时「ーている」的可能形的否定；は表示强调。 意思是：不能够保持～的状态。","example":"例：いつまでも親のすねをかじってはいられない。","translation":"译文：不能永远靠父母养活。"}]},{"category":"关于使役被动","items":[{"point":"～させられる","explain":"「いられる」是「いる」的可能形；ず是否定ない；に表示副词。 此处可以把「ずに」换成「ないで」， 「ずに」比「ないで」语气正式。 意思是：能够保持不做某事的状态。","example":"例：ずっと戸惑わずにいられますか？","translation":"译文：你能一直不困惑吗？"}]},{"category":"关于すら、さえ、こそ","items":[{"point":"～すら","explain":"ず是否定ない；に表示副词。「いられない」是「いる」的可能形的否定；は表示强调。 此处可以把「ずに」换成「ないで」， 「ずに」比「ないで」语气正式。 意思是：不做某事的话就待不住坐不住。 「つもり」常被翻译成“打算”，但是日语的「つもり」的语气要比汉语的“打算”的语气要强得多，所以应该把つもり理解为「強い気持ち」强烈的心情或决心。 如果想说打算做某事时，直接用动词原形不加其他助动词即可。 「つもり」常用「～つもりでいる」的形式，で表示状态，意思是：～的心情很坚定。 注：质问对方时用。 「～させられる」=「～する」，但是与する相比较，させられる有三个语气。 不情愿的 不是自发的 无意中的","example":"例：通信技術の発達の速さに感心せずにはいられない。 例：一体どういうつもりですか？ 例：私は自分がまだまだ若いつもりでいるよ。 例：本当は負けているが、勝ったつもりでいる。 例：お酒を飲みたくないのに、何杯も無理矢理飲まされた。 例：子供たちの発表を聞いて、環境保護について考えさせられた。 例：彼の口車にまんまと乗せられた。","translation":"译文：不能不感叹通讯技术的迅速发展。 译文：你到底想干什么？ 译文：我认为自己还是非常年轻的。 译文：其实输了，可是心里当作自己赢了。 译文：不想喝酒，可是被硬灌了好几杯。 译文：孩子们的发言引起我们对保护环境的深思。 译文：我不知道怎么回事就上了他的当。"},{"point":"～さえ","explain":"举出极端的事物，意思是“连～都”。 语气比「さえ」强。 不跟～ば一起使用。","example":"例：子供すらわかることなのに、どうして大人のあなたがわからないの？","translation":"译文：连孩子都明白的事，为什么你这个大人不明白啊？"},{"point":"～こそ","explain":"举出极端的事物，意思是“连～都”。 用「～さえ～ば」时，意思是：只要～就～。","example":"例：社長にさえ対応のできない問題だから、下っ端の私に対応できるはずがない。 例：反則さえしなければ、勝っていたのに…","translation":"译文：这个问题连社长都无法应对，我这样的小卒子更不可能应对了。 译文：只要不犯规就能赢了，可是现在……"}]},{"category":"关于こと、ひと、もの、ところ","items":[{"point":"～こと","explain":"意思是“正是”。 用「～ばこそ」与「～からこそ」意思一样，但是语气稍正式。意思是：正是因为～。","example":"例：「宜しくお願いいたします。」「こちらこそ宜しくお願いいたします。」 例：子供のためを思えばこそ、アルバイトしながら通学させている。","translation":"译文：“请您多关照。”“我才要请您多关照呢。” 译文：正是因为为了孩子着想才让孩子边打工边上学。"},{"point":"～ひと","explain":"原意是“事情”，还可以代替其他名词。 接在句尾主要表示命令。","example":"例：試験中辞書を使用しないこと。","translation":"译文：考试时不要查字典。"},{"point":"～もの","explain":"原意是“人”，还可以表示其他人或自己。 注：此处既可以指自己也可以指他人。","example":"例：人の噂を撒き散らすのはよくない。 例：人のものを勝手に使わないでよ。","translation":"译文：散布他人的流言不好。 译文：别随便用人家的东西。"},{"point":"～ところ","explain":"原意为“东西，人”。 接在句尾表示强调。","example":"例：時間が経つのは本当に速いものですね。 例：相手にするものか。 例：わたしにはできないものか。","translation":"译文：时间过得真快啊。 译文：谁理他呀。 译文：我就不行吗？"}]},{"category":"关于用两次的词","items":[{"point":"～にしろ～にしろ/～にせよ～にせよ","explain":"原意是“地方”，还有“时间、程度、状况”的意思。 接在不同时态的动词后，表示时间。 表示程度时一般表示程度低，常用「～といったところだ」。","example":"例：今出かけるところだよ。 例：今あの書類を読んでいるところだよ。 例：今帰ってきたところだよ。 例：それは単なる遊びといったところだ。","translation":"译文：现在刚要出门。 译文：现在正在看那个材料。 译文：刚回来。 译文：那只不过是个游戏。"},{"point":"～につけ～につけ","explain":"「しろ」和「せよ」都是「する」的命令形，せよ比しろ语气正式；に表示对象或目的。 此处举出两个例子。 前面可以接名词和谓语词(动词、形容词和形容动词)。","example":"例：寒いにしろ暑いにしろ、どうせ遠くまで行かないから大丈夫だ。 例：気に入るにせよ気に入らないにせよ、引き受けた仕事は最後までやるしかない。","translation":"译文：不管是冷还是热，反正不去远处所以没关系。 译文：不管是喜欢还是不喜欢，接受了的工作只能干到底。"},{"point":"～といい～といい","explain":"「つけ」是「就ける」的连用形；に表示方向或对象。 「～につけ」是举出“就～、关于～”事项的两个例子。 前面可以接名词和谓语词(动词、形容词和形容动词)。 语气正式。","example":"例：結果が良きにつけ悪しきにつけ、まずやってみるのが何よりだ。","translation":"译文：不管结果是坏还是坏，先试着做比什么都强。"},{"point":"～だの～だの","explain":"「～といい」是「～と言う」的连用形。と表示内容。 全意为：不管是说～，还是说是～。","example":"例：顔つきといい、気立てといい、彼は完璧な人だ。","translation":"译文：不管是长相还是说是脾气，他都是个完美的人。"},{"point":"～なり～なり","explain":"だ是です；の表示并列。 前面可以接名词和谓语词(动词、形容词和形容动词)。 全意为举例。","example":"例：疲れただの頭がいいだのと口実を探さないで遅く勉強しなさい。","translation":"译文：别找借口说累了呀头疼了呀什么的，快点儿学习。"},{"point":"～やら～やら","explain":"「なり」的汉字是「也」，在古语中有だ的意思。从汉字的写法来看，「也」相当于表示举例的「や」。 全意为举例。","example":"例：辞書を引くなり他の人に聞くなりどんな方法でもいいから調べてください。","translation":"译文：查字典啦问别人啦，不管什么方法都行，查一下。"},{"point":"～つ～つ","explain":"「やら」和「や」都表示举例。一般「や」接在名词后，「やら」可以接名词和谓语词(动词、形容词和形容动词)。","example":"例：損したやら得したやらもうどうでもいいことだ。 例：飲みすぎて、頭が痛いやら息が苦しいやら、大変でした。","translation":"译文：不管是亏了还是赚了，现在都已经无所谓了。 译文：喝多了，又是头疼又是喘不上气来，痛苦死了。"}]},{"category":"过于","items":[{"point":"～すぎる","explain":"必须是两个对照性的动作。 每个「つ」前面接动词的连用形；「～つ～つ」后面再接一个动词。","example":"例：選手たちはみんな抜きつ抜かれつでゴールインした。 例：彼は部屋で行きつ戻りつしている。","translation":"译文：选手们你追我赶地到达了终点。 译文：他在房间里来回走着。"},{"point":"～あまり","explain":"「ー過ぎる」与前面的谓语词(动词、形容词、形容动词)构成复合词。","example":"例：それは言い過ぎだよ。 例：敬語の使い方は煩わし過ぎる。 例：新宿駅は複雑過ぎる、いつも乗り換えの線が見つからない。","translation":"译文：说得太过分了。 译文：敬语的用法太繁琐了。 译文：新宿站太复杂了，老找不到要换乘的线。"}]},{"category":"过程","items":[{"point":"～間に/～うちに","explain":"「あまり」是「余る」的连用形，作名词。前面一般接名词，表示“由于过于～而～”。","example":"例：驚きのあまり、声も出なかった。","translation":"译文：过于吃惊了，都说不出话了。"}]},{"category":"好不容易","items":[{"point":"せっかく～から","explain":"二者都表示在一定的过程当中。 能够互换时，二者都表示一定的期间。 开始和结束的时间都很明确时，不能用「うちに」。 含糊地指出某个期间，不能用「間に」。 表示在～之前，不能用「間に」。","example":"例：若いうちに/間にいろいろと体験するのは大切だ。 例：1994年から1996年の間に海外留学していた。 例：そのうちにまたお聞きします。 例：冷めないうちにどうぞ。","translation":"译文：年轻时多体验是很重要的。 译文：我在1994年到1996年这段时期在国外留学。 译文：过一段时间我再问您。 译文：趁热吃。"},{"point":"せっかく～のに","explain":"「せっかく」的意思是“好不容易”；から表示原因。","example":"例：せっかく留学に来ているから、しっかり勉強して行きたい。","translation":"译文：好不容易来留学，想以后一直好好学习。"}]},{"category":"好像","items":[{"point":"～みたいだ","explain":"「せっかく」的意思是“好不容易”；のに表示转折，语气消极。","example":"例：せっかくメモを取ったのに、無くしてしまった。","translation":"译文：好不容易记下来了，结果弄丢了。"},{"point":"～ようだ","explain":"意思是“看上去”。 前面直接接名词和谓语词(动词、形容词、形容动词)。 修饰名词时加な，修饰动词时加に。 语气比～ようだ柔和。 常用「まるで～みたいだ」的形式，表示“整个就好像～”。","example":"例：長い間の夢が叶って、まるで夢みたいです。 例：今日みたいな事が二度と起こらないように約束する。 例：日本語ネイティブみたいにしゃべれたいいなあ。","translation":"译文：长期的梦想实现了，简直就像是在做梦。 译文：我保证绝不再发生像今天这样的事。 译文：日语如果能说的像日语母语者那样就好了。"},{"point":"～らしい","explain":"「～様だ」的意思是“～的样子”。 对前面的接续作名词用，对后面的接续作形容动词用。 语气比「～みたい」更加正式、生硬。 常用「まるで～ようだ」的形式，意思是“整个就好像～”。","example":"例：新型機種が登場して以来、ユーザーの数は爆発的に増えているようだ。 例：あの人はどこかで会ったことのあるような気がする。 例：ここに書いてあるように申込書にご記入ください。","translation":"译文：新型机器登场以来，用户的数量好像在暴增。 译文：觉得好像在什么地方见过那个人。 译文：请按照这里写的一样填申请表。"},{"point":"～そうだ","explain":"前面接谓语词。 表示有根据的推断。 前面接名词。 表示符合らしい前面的名词的性质和特点。","example":"例：外に干してある洗濯物が濡れているから、夜中に雨が降ったらしい。 例：あなたらしいアイデアを出してください。","translation":"译文：晾在外面的衣服湿了，夜里可能下雨了。 译文：请你提出一个突出你特点的观点。"},{"point":"～っぽい","explain":"「相」的意思是“看上去”。 前接动词的连用形，形容词和形容动词的词干构成复合词。对后面的接续作形容动词用。 语气柔和。","example":"例：雨が降りそう。 例：おいしそうなご馳走が机の上に並んでいる。 例：村上さんは元気そうに見える。","translation":"译文：看上去要下雨了。 译文：桌上摆着看上去非常好吃的饭菜。 译文：村上看上去身体不错。"},{"point":"～げ","explain":"前面接名词、形容词和动词的连用形。 表示“有～的倾向”。","example":"例：彼は大人なのに子供っぽいところが多い。 例：このかばんは高いけど安っぽく見える。 例：あの人は怒りっぽいけど、実は優しい人です。","translation":"译文：他虽然是大人，孩子气的地方却很多。 译文：这个包挺贵，可是看上去却显得特便宜。 译文：那个人虽然爱生气，但是实际上是个温柔的人。"},{"point":"～ごとし","explain":"汉字是「気」，当作形容动词用。 前接名词、动词的连用形、形容词和形容动词的词干构成复合词。 与「ーそうだ」意思和用法一样，但语气正式。","example":"例：鈴木さんは大人なのに、全然大人げがない。 例：峰村さんは自信ありげに大きな声で質問に答えている。 例：吉田さんは懐かしげに昔のことを話している。 例：荒木さんは退屈げに授業を聞いている。","translation":"译文：铃木是成年人，却没有一点儿大人样。 译文：峰村看上去很自信的样子，大声回答着问题。 译文：吉田看上去非常怀念地谈着过去的事。 译文：荒木好像觉得特别无聊的样子在听着课。"},{"point":"～ごとき","explain":"前面接名词形式的词构成复合名词。 表示带有某种倾向，一般用于不好的事情。","example":"例：ちょっと風邪気味だから、体がだるい。 例：仕事が忙しいから、最近ちょっと疲れ気味です。","translation":"译文：有点儿感冒，浑身没力气。 译文：工作太忙了，最近有些容易疲倦。"},{"point":"～ごとく","explain":"「～如し」是形容词化结尾词，同类的词性的还有「よし」和「なし」。","example":"例：光陰矢の如し。","translation":"译文：光阴似箭。"},{"point":"～めく","explain":"「～如き」是连体形，后面加体言，即直接加名词。","example":"例：花の如き美人が目の前に現れた。","translation":"译文：面前出现了一个如花似玉的美人。"},{"point":"～じみる","explain":"「～如く」是连用形，后面加用言，即加谓语词(动词、形容词、形容动词)。","example":"例：真夏日に草むしりをしていた。汗が滝の如く流れていた。","translation":"译文：炎热的夏天去拔草，汗流浃背。"},{"point":"～とばかりに","explain":"前面接名词构成复合自动词，与「らしい」意思相同，语气正式。 注：自动词修饰名词翻译成汉语为形容词时必须变成过去式。","example":"例：もうすっかり春めいてまいりました。 例：そんな皮肉めいた言い方を止めてよ。","translation":"译文：完全是春意盎然了。 译文：别用那么讽刺的语气说话。"},{"point":"～んばかりに","explain":"自动词「染みる」前面接名词构成复合自动词，意思是“带有～的味道”。 自动词修饰名词翻译成汉语为形容词时必须变成过去式。","example":"例：田舎じみた家を建てたい。 例：彼女はいつも子供じみた格好している。","translation":"译文：我想盖个带有田园风格的房子。 译文：她总是打扮得像个孩子。"},{"point":"～気味","explain":"前面接名词形式的词构成复合名词。表示带有某种倾向，一般用于不好的事情。","example":"例：ちょっと風邪気味だから、体がだるい。 例：仕事が忙しいから、最近ちょっと疲れ気味です。","translation":"译文：有点儿感冒，浑身没力气。 译文：工作太忙了，最近有些容易疲倦。"}]},{"category":"即便～也不～","items":[{"point":"～に～ない","explain":"「ばかり」的意思是“光是、净是、全是”；に表示副词；と表示内容，在此是说的内容。 比喻从表情或状态上推测出全是在说～。 全意为：简直就好像是在说～。","example":"例：彼は、まるで「この事は私には関係がない」とばかりに、平気な顔をしている。","translation":"译文：他表现得像没事似的，简直就好像是在说这件事跟我无关。"},{"point":"～にも～ない","explain":"「ばかり」的意思是“光是、净是、全是”；に表示副词；ん是古语表示推量的助动词む的音变。 前接动词的未然性。 比喻从表情或状态上推测出全是在～。 全意为：简直就好像是在～。","example":"例：親は私の手を千切れんばかりにして、昇進を祝ってくれた。","translation":"译文：父母拉着我的手，简直就好像要把我的手揪掉一样，祝贺了我的晋升。"}]},{"category":"既然","items":[{"point":"～からには","explain":"に表示目的。 「～ない」处要用动词的可能形；に前接动词的原形。 着重将要做某事，同时「～に」和「～ない」之间一般不加其他信息。","example":"例：笑うに笑えない。","translation":"译文：即使要笑也笑不出来。"},{"point":"～以上","explain":"意思是“在～之上”。因为语气强，所以后句接“必须、应该、愿望”等语气强的表达方式。","example":"例：この仕事を引き受けた以上、最後までやり抜くつもりだ。","translation":"译文：既然接受了这个工作，我就决心干到底。"}]},{"category":"假设","items":[{"point":"～なら","explain":"に表示目的；も的意思是也。 「～ない」处要用动词的可能形；にも前接动词的意志形。 着重有要做某事的意志，同时「～にも」和「～ない」之间可以加其他信息。","example":"例：勉強しようにも、外が騒がしいから、集中できない。","translation":"译文：即使想要学习，外面太吵了，没办法集中精力。"},{"point":"～とあれば","explain":"意思是“在～之上”。 因为语气强，所以后句接“必须、应该、愿望”等语气强的表达方式。","example":"例：この仕事を引き受けた以上、最後までやり抜くつもりだ。","translation":"译文：既然接受了这个工作，我就决心干到底。"},{"point":"仮に～とする","explain":"から表示原因，に表示方向，は表示强调。 意思是：在～原因之上。 因为语气强，所以后句接“必须、应该、愿望”等语气强的表达方式。","example":"例：試合に出るからには、全力を尽くしたい。","translation":"译文：既然参加比赛，我们就要全力以赴。"},{"point":"～ば～で","explain":"「なら」在「～と、～ば、～たら、～なら」里假定的意思最强。可以假设过去、现在或将来。 在假设过去是必须注意后句与「ーていた」相呼应，因为表示过去的状态。 名词和形容动词直接加なら。","example":"例：私はあの時よく左右を確認したなら、走ってきた自転車にぶつかっていなかっただろう。 例：今残業しているなら、夜食を用意して届くよ。 例：夕方に小包が届くなら、午前中に買い物を済ませておこう。","translation":"译文：如果我那时左右好好确认的话，就不会撞倒骑过来的自行车了。 译文：要是你现在在加班的话，我给你做夜宵送去。 译文：如果包裹傍晚送到，那上午去买东西吧。"},{"point":"～ものなら","explain":"と表示内容；あれば的意思是“如果有～”。 与「～なら」的意思相同，语气正式、生硬。","example":"例：遠来の客が来るとあれば、腕を振ってご馳走をたくさん用意しよう。","translation":"译文：如果远方的客人要来，那我就抡起胳膊给他们准备一大桌菜吧。"}]},{"category":"结果","items":[{"point":"～た結果、","explain":"と表示内容；する可以代替人和一个动词，此处代替「仮定する」； 「仮に」有时会省略。 可以假设过去、现在或将来。 在假设过去时必须注意后句与「ーていた」相呼应，因为表示过去的状态。 比なら的用法更广，还可以表达如果假设等，比如「～とすれば、～としたら」等。","example":"例：私は弁護師にならなかったとしたら、どんな職業に就いていただろう。 例：仮に毎日単語を10個覚えるとする。一か月で300個を覚えることになる。 例：私が社長だとしたら、きっと全員の給料を上げる。","translation":"译文：假设我没当律师的话，我那时候做什么工作呢？ 译文：假设每天记10个单词，一个月就能记300个单词。 译文：假设我是社长，一定给全体涨工资。"},{"point":"～たところ、","explain":"で前面加动词的过去式，で可以理解为「ところで」，和ても的意思一样表示“即使、尽管、不管”。 和「～たとしても」意思相同，表示“假定即使做了某事，也不～”。 「ーば」可以省略。","example":"例：行きたいけど、行けば行ったで、疲れるだけだ。","translation":"译文：虽然想去，但是即使去了也只不过是受累。"},{"point":"～しまった","explain":"もの接在句尾表示强调；なら表示假设。 前面接动词的意志形。 因为强调“刚要做某事就～”，所以一般引来严重的后果。","example":"例：この会社はとても厳しい。仕事で少しでも失敗しようものなら、首になりかねないよ。","translation":"译文：这个公司特别严格，假设工作中稍微有些失败，就很可能被解雇。"},{"point":"～ば、それまでだ","explain":"表示做了某事后结果发现或得知某事。 注意后面一般不加助词。","example":"例：筆記試験と口頭試験と書類審査を行った結果、候補者を5人に絞った。","translation":"译文：进行了笔试、口试和书面选拔的结果，把候补筛选到了5个人。"},{"point":"～た結果","explain":"表示做了某事后结果发现或得知某事。注意后面一般不加助词。","example":"例：筆記試験と口頭試験と書類審査を行った結果、候補者を5人に絞った。","translation":"译文：进行了笔试、口试和书面选拔的结果，把候补筛选到了5个人。"},{"point":"～たところ","explain":"与「ーた結果」表示相同的意思，表示做了某事后结果发现或得知某事。注意后面一般不加助词。","example":"例：試験を実施したところ、今年の合格の割合は、昨年と比べ、約2割ほど高くなった。","translation":"译文：考试的结果是今年的合格比率比去年增长大约20%。"}]},{"category":"经历","items":[{"point":"～思いをする","explain":"与「ーた結果」表示相同的意思，表示做了某事后结果发现或得知某事。 注意后面一般不加助词。","example":"例：試験を実施したところ、今年の合格の割合は、昨年と比べ、約2割ほど高くなった。","translation":"译文：考试的结果是今年的合格比率比去年增长大约20%。"},{"point":"～体験する","explain":"「始末」的意思是“地步，下场”，一般指不好的结果。","example":"例：彼はいつも睡眠不足で、注意されても聞かない。ついに居眠り運転で事故を起こす始末だ。","translation":"译文：他总是睡眠不足，也不听别人的劝告，结果落到了打盹儿开车出了车祸的地步。"},{"point":"～経験する","explain":"「まで」的意思是“到～的地步”。 全意是：如果～就完蛋了。","example":"例：試験のために一年も準備してきた。試験の前日熱を出せば、それまでだ。","translation":"译文：为了考试准备了一年。要是考试前一天发烧了就完了。"}]},{"category":"尽量","items":[{"point":"～ようにする","explain":"是心理上的经历，「思い」在此的意思是“感觉、感情”；着重用于消极的感情。","example":"例：昨日ある飲食店で嫌な思いをした。 例：親友が遠いところに引っ越してしまって、寂しい思いをした。 例：絶対に勝つと思ったのに、負けてしまって、痛い思いをした。","translation":"译文：昨天我在一个饮食店特别不痛快。 译文：好友搬到很远的地方，我觉得特别寂寞。 译文：我觉得肯定能赢，结果输了，让我特别心痛。"}]},{"category":"举例","items":[{"point":"～でも","explain":"指身体上的经历，去体验某事。","example":"例：20年ほど前の日本のバブル絶頂期を実際に体験した。","translation":"译文：我亲身体验了大概20年以前的日本的泡沫经济的顶峰时期。"},{"point":"～にしても","explain":"是身体和心理双方面的经历。","example":"例：1995年に阪神・淡路大震災を経験した。","translation":"译文：我经历了1995年的阪神淡路大地震。"},{"point":"～とか","explain":"よう的意思是“样子”；に表示方向；する的意思是“做”。 直译为：做成～的样子。意译为：尽量做～。","example":"例：ダイエットしているから、晩御飯は野菜だけ食べるようにしている。","translation":"译文：我在减肥，所以尽量晚饭只吃蔬菜。"},{"point":"～たり","explain":"不特定地举出一个例子。 前面加名词。","example":"例：お茶でも飲みませんか？","translation":"译文：喝点儿茶什么的吗？"},{"point":"～や","explain":"不特定地举出一个例子。 一般前面加名词或谓语词(动词形容词和形容动词)的简体。","example":"例：田中さんの家まで行くにしても、事前に一度電話で連絡した方がいい。","translation":"译文：就是去田中家，最好也事先打个电话。"},{"point":"～やら","explain":"と的意思是“和”；か表示不确定。 前面加名词。 语气柔和。 举例时可以举出一个或多个，所以可以用一次或多次。","example":"例：北京に旅行に行った時、万里の長城とか西太后の別荘だった頤和園とかを回った。","translation":"译文：去北京旅游的时候，转了长城、慈禧的别墅、颐和园等地方。"},{"point":"～だの～だの","explain":"「たり」是「とあり」的音变，と表示内容，あり是「有る」的连用形。 前面接动词和形容词的た形，形容动词是だったり。 语气柔和。 举例时可以举出一个或多个，所以可以用一次或多次。","example":"例：買いたいものはいつもあったりなかったりする。","translation":"译文：想买的东西总是有时候有，有时候没有。"},{"point":"～なり～なり","explain":"表示举例。 语气正式、生硬。","example":"例：本店では、和雑貨やアジアの雑貨や民芸品などを扱っております。","translation":"译文：本店经营日本杂货、亚洲杂货、民间工艺品等。"}]},{"category":"决定","items":[{"point":"～ことにする","explain":"やら和や都表示举例。 一般や接在名词后，やら可以接名词和谓语词（动词、形容词和形容动词）。 语气正式、生硬。","example":"例：損したやら得したやらもうどうでもいいことだ。","translation":"译文：吃了亏了还是赚了便宜了，现在都已经无所谓了。"},{"point":"～ことになる","explain":"だ是です，の是表示并列。 前面可以接名词和谓语词(动词、形容词和形容动词)。","example":"例：疲れただの頭がいいだのと口実を探さないで遅く勉強しなさい。","translation":"译文：别找借口说累了呀头疼了呀什么的，快点儿学习。"}]},{"category":"决心","items":[{"point":"思い切って～","explain":"「なり」的汉字是「也」，在古语中有だ的意思。从汉字的写法来看，「也」相当于表示举例的「や」。 全意为举例。","example":"例：辞書を引くなり他の人に聞くなりどんな方法でもいいから調べてください。","translation":"译文：查字典啦问别人啦，不管什么方法都行查一下。"},{"point":"～つもりだ","explain":"こと表示名词化；に表示方向；可以代替任何一个动词的する在此处的意思是“决定”。 和他动词「決める」意思一样，但是「決める」一般只是单纯的决定，而「～ことにする」着重于有很多选择，决定了其中的一个。体现这个特点的就是表示方向、对象、目的、目标的助词に。 自动词和他动词在使用时，他动词着重有人去做，而自动词不着重做的人。","example":"例：いろいろ考えた結果、留学を止めて就職することにした。","translation":"译文：考虑了很多之后，决定不去留学去上班。"}]},{"category":"觉得","items":[{"point":"～思う","explain":"こと表示名词化；に表示方向；なる意思是“成为”。 和自动词「決まる」意思一样，但是「決まる」一般只是单纯的决定，而「～ことになる」着重于有很多选择，定了其中的一个。体现这个特点的就是表示方向、对象、目的、目标的助词に。 自动词和他动词在使用时，他动词着重有人去做，而自动词不着重做的人。","example":"例：学校から通知があって、今度のコースは開かないことになった。","translation":"译文：学校来了通知，决定了下一次的课程不开了。"},{"point":"～気がする","explain":"「思い切る」的意思是“想了很长时间，之后不再去想”，“思い切って」的意思是“下决心做某事，毅然决然做某事”。","example":"例：思い切って会社を辞めた。","translation":"译文：下决心辞了工作。"}]},{"category":"开端，契机","items":[{"point":"～を皮切りに","explain":"つもり原意是“估算”，但是由于语气强，可以理解强烈的心情。 通过前面接续的动词的时态意思有所改变。 前面加动词的原形，意思是：决心做～。 前面加动词的现在进行时，意思是：以某种强烈的心情认为～。","example":"例：自分の信念を貫くつもりです。","translation":"译文：我决心把我自己的信念贯彻到底。"},{"point":"～をきっかけに","explain":"前面加动词的过去式，意思是：以某种强烈的心情以为～，但是事实相反。","example":"例：負けたけど、勝ったつもりでいる。","translation":"译文：虽然输了，但是当作赢了。"},{"point":"～を契機に","explain":"「思う」有“想、认为、以为、觉得”等意思。","example":"例：このような考え方はあなたにはよくないと思う。","translation":"译文：我觉得这样的想法对你不好。"},{"point":"～をはじめ","explain":"「～気がする」比「思う」更有强调“感觉”的语气，有时候常用「～ような気がする」的形式。 K","example":"例：このやり方はどうしても間違っている気がする。","translation":"译文：总觉得这种方法不对。"}]},{"category":"可能性","items":[{"point":"～可能性がある","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 「皮切り」起源于医学用语，扎针灸的第一针就像是皮肤要裂开的疼痛，意译为“开端”。 全意为：把～当作开端。","example":"例：新型携帯電話は、先月アメリカでの発売を皮切りに、世界各地で販売されている。","translation":"译文：新型手机自打上月在美国的销售以来，在世界各地一直在销售。"},{"point":"～恐れがある","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 「きっかけ」的意思是契机，全意是：以～为契机。","example":"例：その詩人の作品は、テレビのコマーシャルに使われるのをきっかけに、大ブームになった。","translation":"译文：那个诗人的作品用于电视广告之后掀起了热潮。"},{"point":"～かねない","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 全意是：以～为契机，比「～をきっかけに」语气正式、生硬。","example":"例：オイルショックを契機に新エネルギー の研究がどんどん進められている。","translation":"译文：以石油冲击为契机，有关新能源的研究在不断地进展。"},{"point":"～得る","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 「はじめ」的意思是“开始、开端”。 全意是：把～当作开始，以～为首。","example":"例：社長をはじめ、社員全員が開幕式に出席した。","translation":"译文：以社长为首，全体员工都出席了开幕式。"},{"point":"～得ない","explain":"意思是“有～的可能性”；好坏的可能性都可以用。","example":"例：共同研究者を海外から招く可能性がある。 例：著作権違反の可能性がある。","translation":"译文：有可能从海外请共同搞研究的人。 译文：有可能会侵犯版权。"},{"point":"～っ子ない","explain":"名词「恐れ」的意思是“恐怕”，着重指不好的可能性。 与此相同意思的表达方式还有「～心配がある、～危険性がある」等。","example":"例：今日は大雨の恐れがある。","translation":"译文：今天恐怕会下大雨。"},{"point":"～べくもない","explain":"日语里唯一一个“以肯定的形式表达否定的意思，以否定的形式表达肯定的意思”的词。 前面接动词的连用形构成复合词。 「ーかねない」表示“会有不好的可能性”，而「ーかねる」表示“很难做某事”。 二者都有消极的语气。","example":"例：たばこの火をきちんと始末しなければ、事故になりかねないよ。","translation":"译文：不过不把烟头完全掐灭，很可能发生事故。"},{"point":"～ないことはない","explain":"「得る」与前面的动词连用形构成复合动词，意思是“可能～”。 注意此处念「うる」。","example":"例：それはあり得ることだ。","translation":"译文：那很有可能。"},{"point":"～ないものでもない","explain":"「得ない」与前面的动词连用形构成复合动词，意思是“不可能～”。 注意此处念「えない」。","example":"例：それはあり得ないことだ。","translation":"译文：那不可能。"},{"point":"～はずがない","explain":"与前面的动词连用形构成复合动词。 意思是：绝对不可能。","example":"例：宝くじなんて当たりっ子ない。","translation":"译文：奖券这样的东西绝对不可能中。"},{"point":"～わけがない","explain":"「可く」的意思是“可能性”。 意思是：连～的可能性都没有，根本不可能～。","example":"例：東京都心のような土地の高いところでは、一戸建ては簡単に手に入るべくもない。","translation":"译文：在像东京市中心这样土地很贵的地方，买别墅式房子绝对不是件容易的事。"}]},{"category":"肯定","items":[{"point":"ぜひ","explain":"双重否定表示肯定，直译是：没有不～的事情，意译为：有可能～。 注意用「こと」时动词用表示没有的意思的「ない」。","example":"例：どうしても教えてくれと言うなら、教えないことはない。","translation":"译文：如果你非要我告诉你，有可能会告诉你。"},{"point":"きっと","explain":"双重否定表示肯定，直译是：并不是不～，意译为：有可能～。 注意用「もの」时动词用表示不是的意思的「でもない」。","example":"例：難しいが、なんとか工夫すれば、できないものでもない。","translation":"译文：虽然很难，但是想办法好好下工夫，不会做不成的。"},{"point":"～でなくてなんだろう","explain":"「筈」的原意是弓的两端系弦的地方，由于弓的系弦的地方和弦要合适，引申为应该，用于客观性事物。 「～はずがない」的意思是不可能，比「～わけがない」语气客观。","example":"例：激安・速攻ダイエット法、これで簡単に痩せるはずがない。","translation":"译文：便宜快速减肥方法，不可能那么容易瘦下来。"},{"point":"～に決まっている","explain":"「訳」的意思是“道理”。 「～わけがない」的意思是“不可能”，比「～はずがない」语气强。","example":"例：お金は楽に稼げるわけがない。","translation":"译文：钱是不可能轻松地赚的。"},{"point":"～に違いない","explain":"副词「是非」表示愿望强。","example":"例：是非お願いします。","translation":"译文：请您一定帮忙。"},{"point":"～にほかならない","explain":"副词，表示推测。","example":"例：きっと成功する。","translation":"译文：肯定会成功的。"},{"point":"～に相違ない","explain":"「でなくて」是「ではない」的中顿；「なん」的意思是什么；「だろう」表示推测。 意思是：不是～的话，那会是什么啊。意译为：肯定是～。","example":"例：戦争で多くの人が殺されているなんて、これが悲劇でなくてなんだろう。","translation":"译文：战争中很多人都被杀了，这不是悲剧是什么？"}]},{"category":"累加","items":[{"point":"それに","explain":"に表示方向或对象；自动词「決まる」的意思是“定了”；ている表示状态。 全意为：定了就是～。意译为：肯定是～。 前面可以加名词或谓语词(动词、形容词、形容动词)。 语气柔和。","example":"例：よく考えないで言ったことは、後悔するに決まっている。","translation":"译文：不好好想就说，肯定会后悔的。"},{"point":"～に加えて","explain":"に表示方向或对象；「違い」的意思是“不同”；ない的意思是“没有”。 全意为：没有不同。意译为：肯定是～。 前面可以加名词或谓语词(动词、形容词、形容动词)。 语气柔和。","example":"例：そうするだけの理由があるに違いない。","translation":"译文：肯定有那么做的理由。"},{"point":"～上に","explain":"に表示方向或对象；「他」的意思是“其他”；「成らない」的意思是“不成为”。 全意为：不成为其他的～。意译为：肯定是～。 前面可以加名词或谓语词(动词、形容词、形容动词)。 语气正式、生硬。","example":"例：今の成功をもたらしたのは、弛まない努力にほかならない。","translation":"译文：带来今天的成功的正是不懈的努力。"}]},{"category":"历经","items":[{"point":"～にわたって","explain":"に表示方向或对象；「相違」的意思是“互相违反”；ない的意思是“没有”。 全意为：没有互相违反。意译为：肯定是～。 前面可以加名词或谓语词(动词、形容词、形容动词)。 语气正式、生硬。","example":"例：そんな非常識な要求は認められないに相違ない。","translation":"译文：肯定不允许提那么缺乏常识的要求。"}]},{"category":"没有必要","items":[{"point":"～必要はない","explain":"接续词。に表示方向；意思是：在此之上还～。","example":"例：あの店はサービスも最低だ。それに、料理もまずい。","translation":"译文：那个饭馆服务特别差，而且菜也难吃。"},{"point":"～ことはない","explain":"に表示方向；他动词「加える」的意思是：把～加在～上。 前面接名词。","example":"例：大気汚染が進んでいることに加えて、海洋汚染も深刻化してきた。","translation":"译文：大气污染一直在持续，在此之上，海洋污染也越发严重。"},{"point":"～までもない","explain":"に表示方向；意思是：在～之上还～。","example":"例：工事の上に、事故まで起きて、道は余計混むようになった。","translation":"译文：施工加上出了事故，路越发堵了。"},{"point":"～なくていい","explain":"に表示方向；「渡る」的意思是“渡过”。 全意为：历经～期间、遍及～地方。 M","example":"例：手術は十時間にわたって行われた。","translation":"译文：手术进行了10个小时。"},{"point":"～には当たらない","explain":"は是が的强调。 按照字面意思是：没有必要～、用不着～。","example":"例：慌ている必要はないよ、なんとかなるから。","translation":"译文：用不着慌，总会有办法的。"},{"point":"～には足りない","explain":"こと代替的是「必要」。 意思是：没有必要～、用不着～。","example":"例：自信を持ちなさいよ、緊張することはない。","translation":"译文：要有自信，用不着紧张。"}]},{"category":"每","items":[{"point":"～あたり","explain":"も、まで、までも的程度一个比一个强；までも在此处是“到某种地步”的意思。 全意为：用不着～。","example":"例：言うまでもなく、彼の考えは偏っている。","translation":"译文：不用说，他的想法有些偏激。"},{"point":"～につき","explain":"「いい」除了“好”以外，还有“可以、行”的意思。 有时在て形后加も，意思是：即使～也～。 全意为：不做～也行。","example":"例：立ち向かいたくない問題に、無理して立ち向かわなくていい。","translation":"译文：不想面对的问题就不用非要去面对。"},{"point":"～ごとに","explain":"に表示方向或对象；は表示强调；「当たる」的意思是“相当”。 前接名词和动词的简体。 直意为：不相当于～。意译为：没有必要～或值得～。","example":"例：彼の実力を考えると、今回の彼の受賞は驚くには当たらない。 例：彼の行為は称賛には当たらない。","translation":"译文：考虑到他的实力就用不着对他这次的得奖感到吃惊。 译文：他的行为不值得称赞。"},{"point":"～ずつ","explain":"に表示方向或对象；は表示强调；「足る」的意思是“足够”。 前接名词和动词的简体。 全意为：不足于～。","example":"例：充分な準備をしていれば、失敗を恐れるには足りない。","translation":"译文：只要做好充分准备，不用害怕失败。"},{"point":"～おきに","explain":"「あたり」是「当たる」的连用形，作名词用，意思是“相当”。 着重于把总数平均后相当于～。","example":"例：電気代は一日当たり200円です。","translation":"译文：电费平均每天200日元。"},{"point":"～ぶりに","explain":"「つき」是「付く」的连用形，作名词用，意思是“附着”；に表示方向。 意思是：附着于～。","example":"例：水道代は一月につき1000円です。","translation":"译文：水费每月1千日元。"}]},{"category":"每次","items":[{"point":"～度に","explain":"「毎」的意思是“每～”；に是变名词为副词。","example":"例：あいさつの仕方は国ごとに異なる。","translation":"译文：每个国家打招呼的方式都不同。"},{"point":"～につけ","explain":"「ずつ」着重于“每个都有份儿”。","example":"例：この3種類の薬は4時間おきに1錠ずつ飲むこと。","translation":"译文：这3种药必须每隔4小时每种各吃1片。"},{"point":"～つつ","explain":"「おき」是「置く」的连用形，作名词用，意思是“放置”；に是变名词为副词。 着重于“每隔～”。","example":"例：この薬は4時間おきに飲むこと。","translation":"译文：注意这个药每隔4小时吃。"}]},{"category":"面向","items":[{"point":"～向き","explain":"「振る」的意思是“甩，挥”；由于与前面的词构成复合名词，在此用名词的浊音；に是变名词为副词。 意思是：隔了～。","example":"例：田中先生とは15年ぶりに再会した。","translation":"译文：和田中老师隔了15年又相见了。"},{"point":"～向け","explain":"「度」的意思是“～次，～回”；に是变名词为副词。 口语里常用「～たんびに」的形式。","example":"例：注意される度に、人間的に成長する。","translation":"译文：每次别人给指出错误，每次就会更加成熟。"}]},{"category":"难道是","items":[{"point":"まさか～","explain":"に表示方向；「付ける」的意思是“附着”。 直译为：附着于～。意译为：每次～。","example":"例：家族の写真を見るにつけ、会いたくて仕方がない。","translation":"译文：每次看到家里人的照片就想得不行。"}]},{"category":"期限","items":[{"point":"～までに","explain":"つつ表示反复或是继续，在此表示反复，可以理解为汉语的“次次”。 前面接动词的连用形构成复合词。 ーつつ后加も，表示强调。 注意表示转折，意思是：虽然次次～但是～。","example":"例：悪いと知りつつも、ついやってしまうのが、ギャンブルだ。 例：参考書を持って来なければと思いつつ、毎回忘れている。","translation":"译文：虽然次次都知道不好，但还是不由自主地去赌博。 译文：虽然次次想着必须带参考书来，可是每次都忘。"}]},{"category":"强调","items":[{"point":"～あっての","explain":"前面接名词构成复合名词。 由于用的是自动词，意思是：适合于～。","example":"例：それを縦向きにしてください。","translation":"译文：把那个立起来。"},{"point":"～からこそ","explain":"前面接名词构成复合名词。 由于用的是他动词，意思是：为了适合于～而制作的。 N","example":"例：このコースは初心者向けに設けられている。","translation":"译文：这个课程是为初学者设置的。"},{"point":"～ばこそ","explain":"大致分成三种表达方式。 第一种是与表示推测的「～だろう」相呼应，意思是：别是～了吧。 第二种是与「～とは思わなかった」相呼应，意思是：真没有想到～。 第三种是只用一个词，意思是：怎么可能啊。 Q","example":"例：まさか彼はもう知っただろう。 例：まさかあなたがこんな人だとは思わなかった。 例：まさか！","translation":"译文：他不会是已经知道了吧。 译文：真没想到你是这种人。 译文：怎么可能啊！"},{"point":"～だけに","explain":"まで的意思是“到～”；に在此处强调时间点。","example":"例：レポートは午後の5時までに提出すること。","translation":"译文：小论文务必在下午5点前交。"},{"point":"～ばかりに","explain":"此处是「有る」的て形前面直接加名词。 意思是：正是有～才有～。","example":"例：あなたあってのわたしです。","translation":"译文：正是有你才会有我。"},{"point":"～どころか","explain":"から表示原因；こそ的意思是“正是”。 全意为：正是因为～。","example":"例：わからないからこそ、わかるふりをする。","translation":"译文：正是因为不懂才装懂。"},{"point":"～どころではない","explain":"「～ばこそ」与「～からこそ」意思一样，但是语气正式、生硬。","example":"例：忙しければこそ、少ない時間を有効に使えるかもしれない。","translation":"译文：正是因为忙所以可能能够把仅有的时间有效地利用。"},{"point":"まさに","explain":"だけ的意思是“只是”；に表示副词。 全意为：只是因为～。 此处的因果关系不是通过だけに，而是通过上下文推测的，强调原因，一般引起消极的结果。","example":"例：彼の指摘は正しいだけに、かえって私は反発を感じた。","translation":"译文：只是因为他对我的指正太正确了，反倒引起了我的逆反心理。"}]},{"category":"倾向","items":[{"point":"～傾向がある","explain":"ばかり的意思是“光是、全是、净是”；に表示副词。 全意为：全是因为～。 此处的因果关系不是通过ばかりに，而是通过上下文推测的，强调原因，一般引起消极的结果。","example":"例：彼の言葉を信じたばかりに、ひどい目に遭った。 例：外国人であるばかりに、就職が難しい。","translation":"译文：全是因为我相信了他的话，结果倒了大量。 译文：全因为是外国人，就业很困难。"},{"point":"～嫌いがある","explain":"どころ是「ところ」的浊化，比ところ的语气强。 「ところ」表示时间、地点、程度和状况；か表示不确定。 全意为：哪儿是～的时候(程度、情形)啊。","example":"例：もうすぐ試験だよ、遊ぶどころか、寝る時間もないよ。 例：あの薬を飲んで、病気が軽くなるどころか、逆に重くなった。","translation":"译文：马上就该考试了，哪儿是玩儿的时候啊，连睡觉的时间都没有。 译文：吃了那个药，病情哪儿是减轻了啊，反倒加重了。"},{"point":"～一方だ","explain":"どころ是ところ的浊化，比ところ的语气强。 ところ表示时间、地点、程度和状况。 全意为：不是～的时候(程度、情形)。","example":"例：今はばたばたしているから、世間話するところじゃない。","translation":"译文：现在特忙，可不是聊天的时候。"}]},{"category":"轻视","items":[{"point":"～なんか","explain":"「正に」是副词，意思是“正是～、正要～”。","example":"例：これはまさに彼の仕事だ。","translation":"译文：这就是他干的事。"},{"point":"～なんて","explain":"意思是“有～的倾向”，好的坏的倾向都能表示。","example":"例：近頃は人民元のレートが高くなっている傾向がある。","translation":"译文：最近人民币的汇率有升高的趋势。"},{"point":"～ときたら","explain":"意思是：有不好的倾向。","example":"例：彼は仕事をする時一貫性に欠けるきらいがある。","translation":"译文：他做事缺乏一贯性。"},{"point":"～をものともせずに","explain":"意思是：一个劲儿地～。 着重于两个方面的其中的一个方面，因此常用有相对应的反义词的如：「増える和減る，痩せる和太る」等。 前面加动词的一般现在时。","example":"例：都市の環境は悪化する一方だ。","translation":"译文：城市的环境在一个劲儿地恶化。"},{"point":"～ようでは","explain":"なんか是など(～之类的)的口语，表示轻视，有时有自谦的语气。","example":"例：わたしなんか… 例：わたしはうそなんかつきませんよ。","translation":"译文：我哪儿行啊。 译文：我才不会撒谎呢。"},{"point":"～ときたら","explain":"是「～とつ言ったら」的音变，有轻视的语气。意思是：提起～、说到～。","example":"例：彼女ときたら、最近おしゃれのことにはっかり気をつけている。","translation":"译文：说到她，她最近光是注意打扮。"}]},{"category":"全是","items":[{"point":"～だらけ","explain":"なんて有轻视、惊讶的语气。 表示轻视的语气时比なんか表示轻视的语气强。 なんて后面直接加名词，代替「という」，有惊讶或轻视的语气。","example":"例：優等生の彼が不合格だなんて驚いてしまった。 例：裏で人の悪口を言うなんてひどい。 例：絶対に儲かるなんて話は怪しい。","translation":"译文：作为优等生的他不合格真让人吃惊。 译文：在背后说别人的坏话真是太过分了。 译文：说绝对赚钱，让人难以置信。"},{"point":"～まみれ","explain":"「まみれ」接在名词后，意思是：沾满～。","example":"例：ズボンには泥まみれになった。","translation":"译文：裤子上沾满了泥。"},{"point":"～ずくめ","explain":"是「～とつ言ったら」的音变，有轻视的语气。 意思是：提起～、说到～。","example":"例：彼女ときたら、最近おしゃれのことにはっかり気をつけている。","translation":"译文：说到她，她最近光是注意打扮。"},{"point":"～ばかり","explain":"应用了日语里的经典句型「～を～と(に)する(把～当成～)」。 も的意思是都；もの的意思是东西或事情；せず是しない；に表示副词。 意思是：都不把～当回事。","example":"例：彼は困難をものともせずに自分の考えを貫いている。","translation":"译文：他不把困难当回事，把自己的想法贯彻到底。"}]},{"category":"确认","items":[{"point":"～っけ","explain":"よう的意思是“样子”；で表示状态；は表示强调。 意思是：以～的状态。 一般带来不好的结果。","example":"例：これぐらいの困難に挫けるようでは、これから成功するわけがない。","translation":"译文：这么点儿困难就气馁了，要是这个样子的话，今后不可能成功。"}]},{"category":"容易～，难～","items":[{"point":"～やすい","explain":"「だらけ」接在名词后，意思是：全是～净是～。","example":"例：その本には間違いだらけです。","translation":"译文：那本书里全是错。"},{"point":"～がち","explain":"「まみれ」接在名词后，意思是：沾满～。","example":"例：ズボンには泥まみれになった。","translation":"译文：裤子上沾满了泥。"},{"point":"～にかたくない","explain":"「尽くめ」接在名词后，意思是：净是～。 一般用于抽象的事情。","example":"例：今朝からいいことずくめです。","translation":"译文：今天早上开始全是好事。"},{"point":"～にくい","explain":"「ばかり」接在名词和动词后，意思是：光是～、净是～。 口语里加强语气时用「ばっかり」。","example":"例：休日は出かけたくない、どこへ行っても、人ばかりです。 例：最近の学生は遊んでいるばっかりだよ。","translation":"译文：休息日不爱出去，不管去哪儿都是人。 译文：最近的学生光是玩儿。"},{"point":"～づらい","explain":"结尾词，接在谓语词的过去式后。 想不起来的时候或想对方确认的时候用，意思是：～来着。 用于口语。 R","example":"例：彼の名前は何でしたっけ。 例：先生は今日授業中何を言ったっけ。","translation":"译文：他叫什么名字来着。 译文：老师今天上课说什么来着。"},{"point":"～がたい","explain":"「ー易い」与动词的连用形构成复合形容词。 意思是：容易～。","example":"例：日本は住みやすい国です。","translation":"译文：日本是个适合居住的国家。"},{"point":"～かねる","explain":"「ー勝ち」与名词或动词的连用形构成复合名词，变为浊音。 意思是：常出现～、容易～。 一般用于不好的事情。","example":"例：彼女は病気がちです。 例：年をとったせいか、最近は忘れがちになっている。","translation":"译文：她容易生病。 译文：是不是老了，最近变得特别健忘。"}]},{"category":"如果不～，就～","items":[{"point":"～ないと/～なければ/～なかったら/～な","explain":"に表示方向或对象；「難くない」的意思是“不难～”。 前面加名词或动词的简体，但是一般只接「想像する、察する」等词。","example":"例：災害で家族を失った人たちの悲しみは想像に難くない。 例：孫の誕生への彼の喜びは察するに難くない。","translation":"译文：不难想象在灾害中失去亲人有多么痛苦。 译文：不难得知他对孙子诞生有多么高兴。"},{"point":"いなら","explain":"「ー難い」与动词的连用形构成复合形容词。 意思是：很难～。","example":"例：先の説明はわかりにくかった。","translation":"译文：刚才的话不容易懂。"},{"point":"～ことなしに","explain":"「ー辛い」与动词的连用形构成复合形容词，变为浊音。 意思是：很难～。 语气着重心情痛苦。","example":"例：最近の本はわかりづらい。","translation":"译文：最近的书很难懂，让人头疼。"},{"point":"～なしに","explain":"「ー難い」与动词的连用形构成复合形容词，变为浊音。 意思是：很难～。 语气强并且正式。","example":"例：あの格好で大学に行くなんて許しがたい。","translation":"译文：很难允许那种打扮去学校。"},{"point":"～なくして","explain":"日语里独特的一个“以肯定的形式表达否定的意思，以否定的形式表达肯定的意思”的词。 前面接动词的连用形构成复合词。 「ーかねない」表示会有不好的可能性。 而「ーかねる」表示很难做某事，主要是为了避免语气听上去消极，所以用肯定形式表示～ません。","example":"例：申し訳ございませんが、この事はわたしにはわかりかねます。 例：たばこの火をちゃんと消さなければ、事故になりかねませんよ。","translation":"译文：真抱歉，我不太了解这件事。 译文：不把烟掐灭的话，很容易发生事故。"},{"point":"～ぬき","explain":"いなら 「と、ば、たら、なら」有很多区别，大致可以分成两个极端，と是条件性最强，なら是假设性最强。 后句接表示否定的词，意思都可以理解成：如果不～，就不～。","example":"例：研究は厳しいものだから、根性がないと、長続きはできない。","translation":"译文：搞研究是很苦的事情，如果没有毅力是不会坚持下去的。"},{"point":"~ないと/～なければ/～なかったら/～ないなら","explain":"「と、ば、たら、なら」有很多区别，大致可以分成两个极端，と是条件性最强，なら是假设性最强。后句接表示否定的词，意思都可以理解成：如果不～，就不～。","example":"例：研究は厳しいものだから、根性がないと、長続きはできない。","translation":"译文：搞研究是很苦的事情，如果没有毅力是不会坚持下去的。"}]},{"category":"时候","items":[{"point":"～において","explain":"こと在这里是动词名词化；なし的意思是“没有”；に表示副词。 后句接表示否定的词。 意思是：如果不～就不～。","example":"例：担当教師の許可を得ることなしに、履修科目の変更はできない。","translation":"译文：没有得到任课老师的许可，不能更改要学的科目。"},{"point":"～における","explain":"なし的意思是“没有”；に表示副词。 前面直接加名词，后句接表示否定的词。 意思是：如果不～就不～。","example":"例：ノックなしに部屋に入るのはマナー違反です。","translation":"译文：不敲门就进入房间是不礼貌的。"},{"point":"～に際して","explain":"「無くす」的意思是“把～去除”，前面加名词，后句用否定。 意思是：如果不～就不～。","example":"例：部下の信頼なくしては、上司の務めは順調に果たせないだろう。","translation":"译文：没有部下的信任上司就不能顺利完成自己的工作吧。"},{"point":"～にあたって","explain":"「抜く」的意思是“拔掉、除掉”。 用动词的连用形与前面的名词构成复合名词。 后面如果加「に」是变名词为副词，如果加「で」是表示状态。 意思是：没有～、不～。 S","example":"例：朝食ぬきで会社に行く社員が少なくない。 例：先生の指導と先輩の協力ぬきには論文は完成できなかっただろう。","translation":"译文：不吃早饭上班的职员不少。 译文：没有老师的指导和同学的帮助的话论文是不会写好的吧。"},{"point":"～ところだ","explain":"「於く」的意思是“于”；に表示方向。 前面可以接表示时间、地点、状况、团体等名词。 语气正式。 意思是：在～。","example":"例：北京五輪は2008年8月8日において開催される。","translation":"译文：北京奥运会将在2008年8月8日召开。"},{"point":"～ところを","explain":"「～における」是「～において」的连体形，修饰名词。","example":"例：2000年における売り上げは、前年度に比べ、約2倍になった。","translation":"译文：2000年的销售额比前一年度增长了一倍。"},{"point":"～ところに/～ところへ","explain":"「際する」的意思是“～之际”；に表示方向。 语气正式、生硬。","example":"例：皇太子殿下のお誕生日に際して、記者会見が行われた。","translation":"译文：在皇太子殿下的生日之际召开了记者招待会。"},{"point":"～中を","explain":"「当たる」的意思是“相当”；に表示方向。 前面接名词或动词的原形。 意思是：在～之际。 着重于某个特别的时候想要做～或应该做～。","example":"例：開会にあたり、社長に一言ごあいさついただきたいと思います。","translation":"译文：在开始会议之际，请社长致词。"},{"point":"～最中に","explain":"ところ的意思为时间、地点、程度和状况等，此处表示时间。 着重强调动词的不同的时态。","example":"例：今出かけるところだよ。 例：今ホームページを見ているところだよ。 例：今帰って来たところだよ。","translation":"译文：正要出门呢。 译文：正看网页呢。 译文：刚回来。"}]},{"category":"随着","items":[{"point":"～に従って","explain":"ところ的意思为时间、地点、程度和状况等，此处表示时间。 ところ有两种意思，一种是：在～当中抽出时间，を表示移动；另一种是：在～时候被～，此处前后是同一主语。","example":"例：お忙しいところを、恐れ入ります。 例：彼は店で万引きをしているところを監視カメラに撮られた。","translation":"译文：在您百忙之中抽出时间真是不好意思。 译文：他在店里偷东西时被监视器照下来了。"},{"point":"～に伴って","explain":"ところ的意思为时间、地点、程度和状况等，此处表示时间。 「ところに」和「ところへ」的意思都是“在～时候～”。 前后可以用不同的主语。","example":"例：お風呂に入っているところに(へ)、電話がかかってきた。","translation":"译文：洗澡的时候来电话了。"},{"point":"～と共に","explain":"を表示移动。 意思是：在～当中。 比「～ところを」语气正式、生硬。 另外「～中を」除了表示时间外还可以表示地点和状况等，比如：風と雨の中を。","example":"例：お忙しい中を、恐縮です。","translation":"译文：在您百忙之中抽出时间真是不好意思。"},{"point":"～につれて","explain":"名词「最中」的意思是“正在～当中”；に是表示方向。 意思是：正在～的过程当中。 着重于“正在～”，所以如果前面加动词就必须是现在进行时。","example":"例：考えている最中に、話しかけられて困った。 例：授業の最中に電話がかかってきて、急いで教室を飛び出した。","translation":"译文：正在想事情时跟我说话让我很为难。 译文：正上课时来了电话急忙冲出教室。"}]},{"category":"顺便","items":[{"point":"ついでに","explain":"「従う」的意思是“跟从、随从”，由于词的前缀是「した」所以着重上下关系；に表示方向。 语气正式、生硬。","example":"例：通信技術の進歩に従って、情報伝達が速くなってきた。","translation":"译文：随着通讯技术的进步，信息传递越发迅速了。"},{"point":"～がてら","explain":"「伴う」的意思是“伴随”。由于词的前缀是「共」，所以着重同伴关系；に表示方向。 语气正式、生硬。","example":"例：産業の発達に伴って、環境汚染が厳重になってきた。","translation":"译文：随着产业的发展，环境污染越发严重了。"},{"point":"～かたがた","explain":"「共」的意思是“和～一起”；と的意思是“和”；に是变名词为副词。 语气正式、生硬。","example":"例：好きな人と共に人生を歩みたい。","translation":"译文：想和喜欢的人一起共度人生。"},{"point":"～を兼ねて","explain":"「連れる」的意思是“跟着”；に表示对象或方向。 着重于时间的推移。 语气柔和。","example":"例：時間が経つにつれて、昔への記憶がだんだん薄くなってきた。 例：年をとるにつれて、記憶力が悪くなってきた。 例：経験を積むにつれて、物事への対応がますます上手になってきた。","translation":"译文：随着时间的推移，对于过去的记忆越来越淡漠了。 译文：随着年龄的增长，记忆力越来越不好了。 译文：随着经验的积累，处事越来越得体了。"}]},{"category":"特别","items":[{"point":"～てしかたがない","explain":"「序で」是从「次ぐ(接下来)」由来；に是变名词为副词。","example":"例：車を洗うついでに、庭に水を撒いた。","translation":"译文：洗车时顺便往院子里洒了水。"},{"point":"～てしょうがない","explain":"前面接名词或动词的连用形构成复合名词。 语气正式、生硬。","example":"例：散歩がてら、本屋さんに立ち寄った。","translation":"译文：散步时顺便去了趟书店。"},{"point":"～てたまらない","explain":"前面接名词或动词的连用形构成复合名词。 语气正式、生硬。 可以写成汉字是「方々」，着重两方面的事情一起做。","example":"例：帰国のあいさつかたがた、恩師のお宅を訪ねました。","translation":"译文：我要回国了，去老师家拜访跟老师打声招呼。"},{"point":"～てならない","explain":"他动词「兼ねる」的意思是“兼备”。を是接在他动词前的助词。","example":"例：キャンプ地の下見を兼ねて、ドライブに行って来た。","translation":"译文：去开车兜风了，顺便调查了一下野营地。"}]},{"category":"听说","items":[{"point":"～だって/～ですって","explain":"「仕方がない」的意思是“没有办法”；て形表示中顿。 意思是：～得没办法。","example":"例：試合に負けて、悔しくてしかたがない。","translation":"译文：比赛输了，懊悔得没办法。"},{"point":"～そうだ","explain":"「しょう」是「仕様」的口语形式，和「仕方」意思一样；て形表示中顿。 意思是：～得没办法。","example":"例：鍵をかけたかどうか気になってしょうがない。","translation":"译文：特别担心是不是锁门了。"},{"point":"～ということだ","explain":"「堪らない」的意思是“忍不了”；て形表示中顿。 意思是：～得受不了。","example":"例：通勤電車の暖房は効きすぎるから、暑くてたまらなかった。","translation":"译文：上下班高峰电车里的暖气太热了，热得受不了了。"},{"point":"～といわれている","explain":"「成らない」的意思是“不成”；て形表示中顿。 意思是：～得不成。 语气正式、生硬。","example":"例：方向を間違っているような気がしてならない。","translation":"译文：就是觉得一定是把方向弄错了。"},{"point":"～とされている","explain":"だ接在句尾。 名词和形容动词直接加だ，形容词和动词用的是んだ的形式。んだ接在句尾，加强语气。 「って」是表示内容的「と」的口语形式。 「～だって」用于口语，表示听说或某人说话的内容。 「～ですって」多用于女性。","example":"例：明日は授業のオリエンテーションだって。 例：明日は雨が降るんだって。","translation":"译文：听说明天是课程介绍。 译文：听说明天要下雨。"}]},{"category":"同时","items":[{"point":"～と同時に","explain":"前面接听说的整个句子。","example":"例：新しいデザインの車は来月発売されるそうだ。","translation":"译文：据说新设计的车下月销售。"},{"point":"～と共に","explain":"前面接听说的整个句子；と表示内容。 语气正式、生硬。","example":"例：今年の夏は涼しいので、クーラーの販売台数は激減したということだ。","translation":"译文：今年夏天很凉快，听说空调的销售量急剧减少。"},{"point":"～か～ないかのうちに","explain":"前面接听说的整个句子；と表示内容；「言われる」的意思是“被说”。 用现在进行时表示持续的状态。","example":"例：コラーゲンは美容を保つには欠かせないものだといわれている。","translation":"译文：大家都说胶原对于保持美容是不可缺少的。"}]},{"category":"痛快地","items":[{"point":"思い切り～","explain":"前面接听说的整个句子；と表示内容；される是する的被动式，する可以代替任何一个动词，される此处代替了言われる。 用现在进行时表示持续的状态。 语气正式、生硬。","example":"例：現在の医療技術では、この種の病気はまだ治す方法がないとされている。","translation":"译文：据说以现在的医疗技术，还没有治这种病的办法。"},{"point":"思い存分～","explain":"と的意思是“和～”；に表示时间。","example":"例：結婚と同時に苗字も変えた。","translation":"译文：结婚的同时还变更了姓氏。"}]},{"category":"为了","items":[{"point":"～には","explain":"と的意思是“和～”；に变名词为副词。 「と共に」既可以表示“同时”也可以表示“一起”。","example":"例：飛行機のチケットを買うと共に向こうのホテルも取った。","translation":"译文：买了机票的同时还订了当地的饭店。"},{"point":"～ように","explain":"两个か都表示不确定，前面分别接同一个动词的肯定和否定形式； 「うち」是“在～之内”；に强调方向。 全意是：在某种动作是在做还是不做地过程当中下一个动作就开始了。意译为：大概同时发生。 思い切り~ 「思い切る」的意思是“想了很长时间之后不再去想”，连用形「思い切り」的意思是：痛快地做～。 思う存分~ 「存分」的意思是“所有的部分”。 全意为：想的所有的部分。意译为：完全按照想的去痛快地做～。 W","example":"例：授業の終わりのベルが鳴るか鳴らないかのうちに、学生は教室を飛び出した。 例：人前で思い切り泣いたり笑ったりするのは私の性格ではない。 例：今日はご馳走するから、思う存分食べてください。","translation":"译文：大概在下课铃响的同时，学生冲出了教室。 译文：在人前痛快地哭、痛快地笑不是我的性格。 译文：今天我请客，痛痛快快地吃吧。"},{"point":"～ために","explain":"に表示目的；は表示强调。 前面可以接名词或动词的原形。 是表示目的时的最简洁的说法。","example":"例：いい就職ができるには、普段からの努力以外に運も大事だと思う。","translation":"译文：能够找到一个好工作，除了平时的努力以外运气也很重要。"},{"point":"～んがために","explain":"よう的意思是“样子”；に是变名词为副词。 原意是：为了成为某种样子而做某事。 特点有两个，第一是客观叙述，所以前面接动词的可能形；第二是前后既可以是同一主语，也可以是不同的主语。","example":"例：留学できるようにいろいろな事前準備をしている。 例：すべてのレベルの学生がわかるように、わかりやすく説明した。","translation":"译文：为了能够留学正在做各种事先准备。 译文：为了所有水平的学生都能懂，我做了通俗易懂的译文。"}]},{"category":"无意识","items":[{"point":"～ともなく/～ともなしに","explain":"ため的意思是“为了”；に是变名词为副词。 有两个特点：第一是主观愿望强，所以前面接动词的原形；第二是前后必须是同一主语。","example":"例：試験に合格するために、一秒たりとも無駄にせず勉強に取り組んでいる。","translation":"译文：为了考试能考过，即使是一秒钟都致力于学习。"}]},{"category":"相反","items":[{"point":"～に反して","explain":"ん是古语表示推量的助动词む的音变，前接动词的未然性；が是接续；ため是“为了”；に是变名词为副词。 全意为：～しようと思ってそのために～。 语气最正式、生硬。","example":"例：真実を明らかにせんがために、あらゆる手を尽くした。","translation":"译文：为了弄清真相，想尽了一切办法。"},{"point":"～に対して","explain":"もなく/~ともなしに と的意思是“和”；も是“也”；なく和なしに都是否定。 意译为：似做非做，无意识地做～。 前后用同一个动词。","example":"例：眠いから、テレビを見るともなしに見ている。","translation":"译文：困了，似看非看地在看电视。"},{"point":"～一方で","explain":"に表示对象。 一般接「期待、予想、予測」等词。","example":"例：地元の住民の予想に反して、住宅の値段が上がる一方だ。","translation":"译文：与当地居民的预想相反，住宅价格一个劲儿地在上涨。"},{"point":"～と思いきや","explain":"意思是：与～相反。","example":"例：彼は仕事上しっかりしている反面、金使いが荒い。","translation":"译文：他在工作上非常认真严谨，另一面，花钱却大手大脚。"},{"point":"～にひきかえ","explain":"に表示对象；「対して」表示对比。 前面接名词。","example":"例：姉が働き者であるのに対して、妹は怠け者だ。","translation":"译文：姐姐非常能干，与其相对照，妹妹很懒。"},{"point":"~反面","explain":"意思是：与～相反。","example":"例：彼は仕事上しっかりしている反面、金使いが荒い。","translation":"译文：他在工作上非常认真严谨，另一面，花钱却大手大脚。"}]},{"category":"想做","items":[{"point":"～たい","explain":"で是です的中顿。意思是：一方面～，另一方面～。","example":"例：若い人の就職難が問題になる一方で、多くの分野で人手が足りない。","translation":"译文：年轻人的就业难成了问题，另一方面，在很多领域里人手却不够。"},{"point":"～てほしい","explain":"と表示内容；「思う」的意思是“想”；「き」是表示过去式的助动词；「や」用于反语。 全意是：与想的相反。","example":"例：二人は大喧嘩した。きっと分かれると思いきや、和解した。","translation":"译文：两个人太吵了一架，我想他们肯定要分手了，结果两个人和解了。"},{"point":"～ようと","explain":"「引き替える」的意思是“交换”；に表示对象。 前面接名词。 意思是：与～相反。 要用有对照性的词。","example":"例：旺盛な好奇心と元気さにひきかえ、語学力と忍耐力がほとんどない。","translation":"译文：有旺盛的好奇心和精力，与此相反，却几乎没有什么外语能力和忍耐力。"},{"point":"～べく","explain":"「ーたい」是动词的后缀，与动词的连用形构成复合形容词，表示“想做～”。","example":"例：家を買いたい。","translation":"译文：我想买房子。"}]},{"category":"形容词变名词","items":[{"point":"～さ","explain":"表示欲望的「ほしい」接在动词的て形后，表示“想让别人做～”。","example":"例：彼に家を買って欲しい。","translation":"译文：我想让他买房子。"},{"point":"～み","explain":"动词的意志形，意志的英语是 will，日本的动词的意志形可以理解为英语的 will do sth.。表示愿望。 动词的意志形一般要接と才能构成意志形，后面还要接另一个动词。","example":"例：日本語の語学力を身につけようと努力している。","translation":"译文：我努力在要提高我的日语水平。"},{"point":"～め","explain":"「可く」通过字面可以得知意思是“可～”，在此着重强调“可要～”。 由于后缀是「く」，所以作为副词用。前面接动词的原形。","example":"例：ウィルスの感染経路を明らかにするべく綿密な調査が行われた。","translation":"译文：要调查清楚病毒的感染途径，展开了严密的调查。"}]},{"category":"形容状态","items":[{"point":"～まま","explain":"形容词词干后加さ，着重具体的事物。","example":"例：長さ、幅、高さを量ってください。","translation":"译文：量一下长宽高。"},{"point":"～っぱなし","explain":"形容词词干后加み，着重抽象的事物。","example":"例：彼の話には深みがある。","translation":"译文：他说话有深度。"}]},{"category":"也就是说","items":[{"point":"つまり(即ち)～わけだ","explain":"形容词词干后加め，作为形容动词用。 意思是：稍微～。","example":"例：少し小さめのがありますか。 例：お塩を少なめに入れてください。","translation":"译文：有没有稍微小一点儿的。 译文：稍微少放些盐。"}]},{"category":"一边～一边","items":[{"point":"～ながら","explain":"名词「まま」的意思是样子。 前面接动词时必须是过去式。","example":"例：久しぶりに実家に帰ったが、周りは昔のままです。 例：化粧したまま眠るのは肌によくないよ。","translation":"译文：隔了好久又回到父母家，周围还是原来的样子。 译文：带着妆睡觉对皮肤不好。"},{"point":"～一方で","explain":"「ぱなし」是表示放置不管的「放す」连用形，作名词使用。 由于与前面的动词的连用形构成复合名词，发生了浊化，促音在此是加强语气。 全意为：放置不管。 Y つまり(即ち)~わけだ 「つまり」和「わけだ」常一起搭配使用，「即ち」语气正式。 一边~一边","example":"例：節電を考えれば、電気をつけっぱなしにしてはいけない。 例：何も言わなかったというのは、つまり認めてくれたわけかな。","translation":"译文：考虑到节电，不随手关灯不行。 译文：什么都没说，也就是同意了吧。"},{"point":"～かたわら","explain":"前面加动词的连用形，表示“一边～一边～”。","example":"例：日が照りながら雨が降っている。","translation":"译文：一边出着太阳一边下着雨。"},{"point":"～そばから","explain":"で是です的中顿。 原意为：一方面～，另一方面～。 着重于对照性的动作。","example":"例：人前でいいと言っている一方で、裏で嫌だと言っている。","translation":"译文：一边在人前说可以，一边在背后又说不愿意。"}]},{"category":"与～一起","items":[{"point":"～と一緒に","explain":"名词「傍ら」的前缀的「片」的意思是两个里的一个，从汉字部首是单立人来记忆，意思是一个人同时做两件事情。","example":"例：学校の教師で勤めている傍ら、翻訳の仕事もしている。","translation":"译文：一边是学校老师，一边又干翻译的工作。"},{"point":"～と共に","explain":"名词「そば」的意思是“旁边”；「から」的意思是“从”。 直译为：从旁边就～，意译为：一边～一边～。 与~一起","example":"例：聞いたそばから忘れてしまう。 例：親が片付けるそばから、子供は散らかしてしまう。","translation":"译文：一边听一边忘。 译文：家长一边收拾，孩子一边弄乱。"},{"point":"～と相まって","explain":"と的意思是“和”；に是变名词为副词。 意思是：和～一起。","example":"例：彼氏と一緒に旅行に行ってきた。","translation":"译文：和男友一起去旅行了。"}]},{"category":"一～就～","items":[{"point":"～と","explain":"と的意思是“和”；に是变名词为副词。 意思是：和～一起。此外还可以表示同时。","example":"例：知識を深めると共に、経験も積んだ。","translation":"译文：加深了知识也积累了经验。"},{"point":"～かと思うと","explain":"と的意思是“和”；「相まって」的意思是“相互作用”。 一~就~","example":"例：実力と運と相まって、彼を成功に導いた。","translation":"译文：实力和运气的相互作用把他引向了成功。"},{"point":"～た途端に","explain":"と是「と、ば、たら、なら」里条件性最强的，表示有某个条件就会有某个结果。","example":"例：長時間本を読むと目が疲れる。","translation":"译文：长时间看书眼睛就会疲劳。"},{"point":"～や(否や)","explain":"か表示不确定；と表示内容；「思う」的意思是“想”；と表示条件。 全句强调刚在想某事还没有确定时就发生了下一件事，意译动作快。","example":"例：信号が青になったかと思うと、すぐに赤に変わった。","translation":"译文：红绿灯刚变成绿灯，马上又变成红灯了。"},{"point":"～なり","explain":"「途端」起源于“一条道路的边缘或尽头”；に表示方向，常可以省略。 原意为：刚刚走完某条路到其尽头。意译为：刚刚做完某事就发生了下一件事情，形容快。 前面必须接动词的过去式。","example":"例：布団に入った途端、ぐっすり眠ってしまった。","translation":"译文：刚钻进被窝就呼呼大睡了。"},{"point":"～が速いか","explain":"两个「や」可以理解为举例；「否」是否定。 要举出一个例子，在要举还是不举，还没有确定时就发生了下一件事，形容快。 前面必须接动词的原形。 语气正式、生硬。","example":"例：新商品の販売が開始されるや否や注文が殺到した。","translation":"译文：新商品的销售刚开始，订货就蜂拥而至。"},{"point":"~次第","explain":"「次」是“第二”的意思，「第」在此处也是“第二”的意思。意思是一个动作发生了以后第二步马上就发生下一个动作，形容快。与动词的连用形构成复合名词。语气正式、生硬。","example":"例：決まり次第ご連絡いたします。","translation":"译文：定了以后马上跟您联系。"}]},{"category":"应该，必须","items":[{"point":"～なければならない/いけない/だめだ","explain":"「なり」的汉字是「也」，而日语的假名「や」是从汉字的「也」由来，因此「～なり」和「～や(否や)」的意思和用法以及接续方式都完全相同。 语气正式、生硬。","example":"例：私が作った料理を一口食べるなり、父は変な顔をした。","translation":"译文：爸爸刚吃了一口我做的饭，马上就显出了奇怪的表情。"},{"point":"～べきだ","explain":"が表示接续；「速い」的意思是“快”；か是不确定。 形容动作非常快还没有确定时下一件事情就发生了。 前面接动词的原形或过去式都可以。 语气正式、生硬。","example":"例：地震だと呼ぶが速いか、みんな机の下に潜り込んだ。","translation":"译文：刚一喊地震了，大家都钻进了桌子底下。"},{"point":"～はずだ","explain":"「次」是“第二”的意思，「第」在此处也是“第二”的意思。 意思是一个动作发生了以后第二步马上就发生下一个动作，形容快。 与动词的连用形构成复合名词。 语气正式、生硬。","example":"例：決まり次第ご連絡いたします。","translation":"译文：定了以后马上跟您联系。"},{"point":"～わけだ","explain":"「なければ」是表示否定的「ない」和表示如果的「ば」一起接续的形式；「ならない」的意思是“不成”；「いけない」的意思是“不行”；「だめ」的意思是“不行”。 三种说法的正式、生硬程度递减。 全意为：不～不行。","example":"例：試験を控えているから、集中して頑張らなければいけない。","translation":"译文：面临考试，必须集中精力加油。"},{"point":"～わけにはいかない","explain":"「可き」从字面上可以理解为“可要做某事”。 着重于责任和义务。","example":"例：この事について事前に許可をもらうべきだ。","translation":"译文：关于这件事，应该事先得到许可。"},{"point":"～ものではない","explain":"「筈」的原意是弓的两端系弦的地方，由于弓的系弦的地方和弦要合适，引申为“应该”，用于客观性事物。","example":"例：もうそろそろ着くはずだ。","translation":"译文：应该快到了吧。"}]},{"category":"有做～的意思","items":[{"point":"～ようとする","explain":"「訳」的原意是“道理”，意译为从道理上来讲应该。","example":"例：日本に長年いたから、日本語が上手なわけだ。","translation":"译文：在日本待了很多年，日语当然好了。"},{"point":"～ようとしない","explain":"「訳」的原意是“道理”；に表示方向；は表示强调；「いかない」是“往～的方向走”。 直译为：不朝～的道理的方向去，意译为：从基本道理上来讲都不应该～、不能～、不可能～。","example":"例：教師として遅刻するわけにはいかない。","translation":"译文：作为一名教师，从起码的道理上来讲都不能迟到。"},{"point":"～そうもない/～そうにない","explain":"もの接在句尾表示强调。 此处「ものではない」的意思是由强调引申为“不应该做～”。 有做~的意思","example":"例：小さい子供を一人で遠くに遊びに行かせるものではない。","translation":"译文：不应该让小孩子一个人去远地方玩儿。"}]},{"category":"又不是～","items":[{"point":"～じゃあるまいし","explain":"动词的意志形，意志的英语是 will，日本的动词的意志形就可以理解为英语的 will do sth.。表示愿望。动词的意志形一般要接と才能构成意志形，然后后面还要接另一个动词。 这里用的是可以代替任何一个动词的する。 全意表示要做～。 着重于本人意志。","example":"例：今メールを出そうとしている。","translation":"译文：现在正要发信息。"}]},{"category":"与～有关","items":[{"point":"～に関係がある","explain":"动词的意志形，意志的英语是 will，日本的动词的意志形就可以理解为英语的 will do sth.。表示愿望。动词的意志形一般要接と才能构成意志形，然后后面还要接另一个动词。 「ーようとしない」表示根本没有做～的意思。 由于用的是动词的意志形，所以着重于本人意志。","example":"例：もう遅いのに、子供は全然寝ようとしない。","translation":"译文：都已经这么晚了，孩子一点儿要睡觉的意思都没有。"},{"point":"～に関わる","explain":"そう前面接动词的连用形表示“好像”；も的意思是“连”；如果用に表示副词；ない是“没有”。 直译为：连～的好像都没有。 着重于看上去。 又不是~","example":"例：雨が止みそうにない。 例：この調子なら、時間通りに終わりそうにない。","translation":"译文：雨没有停的意思。 译文：照这个样子的话，不可能按时结束。"},{"point":"～に係る","explain":"じゃ是では的口语形式；まい在此是“决不”；し的意思是“又”。 与~有关","example":"例：子供じゃあるまいし、こんな小さい礼儀もわからないの？","translation":"译文：又不是孩子，连这点儿小节礼都不懂吗？"}]},{"category":"越～越～","items":[{"point":"～ば～ほど","explain":"に表示对象。 意思是：与～有关系。","example":"例：この事は私には関係がない。","translation":"译文：这事跟我没关系。"}]},{"category":"原因","items":[{"point":"～から","explain":"に表示对象。 意思是：与～有关系。 语气正式、生硬。","example":"例：昇進に関わる問題だから、気をつけよう。","translation":"译文：这是有关晋升的问题，得注意点儿。"},{"point":"～ので","explain":"に表示对象。 意思是：与～有关系。 语气正式、生硬。 越~越~","example":"例：賃金改定に係る案はまだ最終決定の段階には入っていない。","translation":"译文：有关工资改革的方案还没有进入最终决定的阶段。"},{"point":"～ため","explain":"ば表示条件，意思是“如果”；ほど是程度高。 前后用同一个词。可以省略ば单独用ほど。","example":"例：習えば習うほど難しく感じる。","translation":"译文：觉得越学越不懂。"},{"point":"～せいで","explain":"接在谓语部分后，语气有时有些主观。","example":"例：内陸だから、空気が乾燥している。","translation":"译文：因为是内陆所以空气很干燥。"},{"point":"～によって","explain":"动词和形容词之后直接加ので，形容动词和名词加な再接ので。 语气客观。","example":"例：経験がまだ浅いので、宜しくお願いいたします。","translation":"译文：经验不足，请多关照。"},{"point":"～が故に","explain":"「為」的意思是“因为”。 语气正式、生硬。","example":"例：レポート提出の締め切りに間に合わなかったため、減点されてしまった。","translation":"译文：由于没有赶上小论文的提交期限被减了分。"},{"point":"～次第で","explain":"「かげ」是“阴影”的意思；お接在名词前表示礼貌；で表示原因。 意思是：托～的福，引出好的结果。","example":"例：若い時から体を鍛えてきたおかげで、病院には無縁だ。","translation":"译文：从年轻时开始就一直锻炼身体，所以跟医院无缘。"},{"point":"～とあって","explain":"「所為」的语气消极，意思是“怪～”(如：天気のせいだよ。就怪天气不好)； で表示原因。引出不好的结果。","example":"例：道が混んだせいで、遅れてきた。","translation":"译文：堵车所以来晚了。"},{"point":"～て/～こととて","explain":"「由る」的意思是“由于”；に表示对象。 前面接名词。 语气正式、生硬。","example":"例：先端技術を駆使することによって、より便利な生活ができるようになった。","translation":"译文：由于能够使用先进技术，所以生活变得更加方便了。"},{"point":"~おかげで","explain":"「かげ」是“阴影”的意思；お接在名词前表示礼貌；で表示原因。意思是：托～的福，引出好的结果。","example":"例：若い時から体を鍛えてきたおかげで、病院には無縁だ。","translation":"译文：从年轻时开始就一直锻炼身体，所以跟医院无缘。"},{"point":"~とて/~こととて","explain":"と表示内容；て可以理解为「あって」省略了「あつ」。有时前面接名词こと，表示内容的と前面可以直接接名词。语气正式、生硬。","example":"例：急なことで、ゆっくりごあいさつにも伺えませんでした。","translation":"译文：因为非常突然，都没能好好去打招呼。 Z"}]},{"category":"在","items":[{"point":"～に","explain":"が表示接续，有时会省略；名词「故」的意思是“缘故”；に是变名词为副词。 前面直接加名词和谓语词(动词、形容词和形容动词)。 语气正式、生硬。","example":"例：友人からの忠告を聞かなかったが故に、この始末になってしまった。","translation":"译文：由于没有听朋友的忠告，才落到了这个地步。"},{"point":"～で","explain":"「次」的意思是“下一个”，“第」在此处的意思是“第二个”；で表示原因。 着重于有几个原因，直译为：由于这几个原因所以～。","example":"例：以上のような次第で退学させていただきます。","translation":"译文：由于以上原因，请让我退学。"},{"point":"～にあって","explain":"と表示内容；ある的意思是“有”；表示中顿的て形在这里着重因果关系。 语气正式、生硬。","example":"例：開店セールとあって、店内は客でごった返していた。","translation":"译文：由于是开店促销，商店里挤满了顾客。"},{"point":"～において","explain":"て/~こととて と表示内容；て可以理解为「あって」省略了「あつ」。 有时前面接名词こと，表示内容的と前面可以直接接名词。 语气正式、生硬。 Z","example":"例：急なことで、ゆっくりごあいさつにも伺えませんでした。","translation":"译文：因为非常突然，都没能好好去打招呼。"},{"point":"～にかけては","explain":"に表示“方向、对象、目的、目标”，还可以接在具体数字的时间后。 如果用于地点强调的是方向。","example":"例：ここに書いてください。","translation":"译文：写在这里。"},{"point":"～する上で","explain":"で表示“在某个地方做某事、交通和方法、范围、程度、原因、状态”。 如果用于地点强调范围或动作。","example":"例：ここで書いてください。","translation":"译文：在这里写。"}]},{"category":"在～之后","items":[{"point":"～て","explain":"ある的意思是“在”；に表示“方向、对象、目的、目标”。 语气正式、生硬。","example":"例：あの事は私にあってまだ鮮明に覚えている。","translation":"译文：那件事对我来说还记忆犹新。"},{"point":"～てから","explain":"「於く」的意思是“于”；に表示方向；前面可以接表示时间、地点、状况、团体等名词。 意思都是：在～。 语气正式、生硬。","example":"例：上級者において、発音の重要性と文法の煩わしさをますます感じていると思う。","translation":"译文：我认为高级班的学生越发感到了发音的重要性和语法的繁琐性。"},{"point":"～てからというもの","explain":"「かける」意为“大面积的覆盖”；に表示方向；は表示强调。 意思是：在～方面。","example":"例：気立てにかけては誰にも負けない。","translation":"译文：在脾气秉性方面我不输给任何人。"},{"point":"～てからでないと","explain":"で表示范围；前面必须加动词的原形。 意思是：在～方面上。 在~之后","example":"例：適当な運動をするのは、健康と美容を保つ上で大切です。","translation":"译文：适当的运动在保持健康和美容方面非常重要。"},{"point":"～て以来","explain":"动词的て形表示中顿，说明后面还有另一个动作，用于动词和动词的单纯接续。 可以在一个句子中用数次。","example":"例：本を読んで、昼ごはんを食べて、昼寝して…","translation":"译文：看书，吃午饭，睡午觉……"},{"point":"～たら","explain":"表示中顿的动词的て形后接表示从此开始的から，表示完全做完前面的动作之后接下来就做下面的动作。 只能在句子中用一次。","example":"例：ご飯を食べてから行きます。","translation":"译文：吃晚饭后马上去。"},{"point":"～た後で","explain":"表示中顿的动词的て形后接表示从此开始的から，表示完全做完前面的动作之后接下来就做下面的动作；用「という」是为了接续名词；もの表示强调。 强调契机。","example":"例：恋人が帰って来てからというもの、彼女は見違えるほど元気になった。","translation":"译文：恋人回来以后，她就像变了一个人一样，特别精神。"},{"point":"～た末に","explain":"表示中顿的动词的て形后接表示从此开始的「から」，表示完全做完前面的动作之后接下来就做下面的动作；「でない」的意思是“不是”；と表示条件。 全意为：如果不是做了～的话。 强调契机。","example":"例：基礎練習のプロセスを経験してからでないと、その重要性がわからない。","translation":"译文：不经历基础练习的过程，之后是不会体会到其重要性的。"},{"point":"～たあげく","explain":"表示中顿的动词的て形后面加「以来」。 意思是：在做了～以来。","example":"例：日本語を習って以来、日本語の面白さを充分味わってきた。","translation":"译文：自学习日语以来，一直充分地体会着日语的有趣之处。"},{"point":"～た上で","explain":"动词的过去式「た」形后接表示假设「ら」，意思是“做了～之后”，由于有假设的含义所以一般用于将来时动作。 「ーたら」，由于有假设的含义，如果用过去式的话，有“发现了”的意思。","example":"例：家に着いたら連絡してね。 例：窓を開けたら雪が降っていた。","translation":"译文：到家后给跟我联系啊。 译文：打开窗户，发现下雪了。"},{"point":"～たが最後","explain":"动词的过去式た形后接「後で」。 意思是：在做完了～之后。 强调“之后”。","example":"例：家を建てた後で後悔した。","translation":"译文：盖完了房子后悔了。"}]},{"category":"在～之前","items":[{"point":"～前に","explain":"动词的过去式た形后接「末に」；に是变名词为副词。 意思是：在做完了～之后。 语气正式、生硬。","example":"例：苦しみ抜いた末に勝ち取った。","translation":"译文：长期受苦之后取得了胜利。"},{"point":"～に先立ち","explain":"「挙句」原意是日本的连歌的最后的句子，用于动词的过去式た形后，表示“在做完了～之后”，但是意译要经历很长时间或很多事情。","example":"例：さんざん悩んだあげく、辞職をすることにした。","translation":"译文：头疼了很长时间后决定辞职。"}]},{"category":"正在","items":[{"point":"～ている","explain":"动词的过去式た形后接「上で」表示范围。 意思是：在做完～的基础之上。 着重于步骤和基础。","example":"例：親とよく相談した上でご返事します。","translation":"译文：和父母亲好好商量之后给您回信。"},{"point":"～つつある","explain":"が是接续词。用于动词的过去式后。 全意为：做了～以后就一发不可收拾。 在~之前","example":"例：あの人はカラオケが好きで、マイクを握ったが最後、他の人には渡さない。","translation":"译文：那个人喜欢唱歌，握住了麦克风后就一发不可收拾，麦克风谁也不给。"}]},{"category":"值得做","items":[{"point":"～に値する/～に値しない","explain":"に是变名词为副词。 前面要接动词的一般现在时。 动词的一般现在时既表示一般性的动作又表示将来性的动作，在此是表示将来性的动作，此处表示将来性的动作。 全意为：在将要做～之前。","example":"例：出かける前に、火元をちゃんと確認してください。","translation":"译文：出门前好好确认火源。"},{"point":"～に足る/～に足りない","explain":"に表示方向；「先」是“时间在～之前”；「経つ」是“经过”。 前面要接动词的一般现在时。 动词的一般现在时既表示一般性的动作又表示将来性的动作，在此是表示将来性的动作，此处表示将来性的动作。 全意为：发生在～之前。 语气正式、生硬。","example":"例：新車の発売に先立ち、展示会が開かれた。","translation":"译文：在销售新车之前开了展览会。"},{"point":"～甲斐がある/～甲斐がない","explain":"动词的现在进行时有两个意思：一个是正在做，另一个是持续的状态。","example":"例：今その問題を議論しているよ。","translation":"译文：我们正在讨论那个问题。"},{"point":"～には当たらない","explain":"つつ前面接动词的连用形构成复合词。 着重于“一步一步地正在”。","example":"例：町の様子は変わりつつある。","translation":"译文：街道的样子在一点点地发生变化。"},{"point":"~(に)足る/-(に)足りない","explain":"「足る」的意思是“足够”；に表示方向。直译为：足于～。前面加名词或动词原形。「～に足りない」还可以翻译成：没有必要～。","example":"例：彼は信頼に足る人物です。 例：こんなに高い実力なら、彼は恐れるに足りない。","translation":"译文：他是个值得信任的人。 译文：以这么高实力，他用不着害怕。"}]},{"category":"只要","items":[{"point":"～と","explain":"値する/~に値しない 名词「値」的意思是“数值”，加上する后变为动词；に表示方向。 前面加名词或动词原形。","example":"例：彼がやったことは賞賛するに値する。","translation":"译文：他做的事值得称赞。"},{"point":"～限り","explain":"「足る」的意思是“足够”；に表示方向。 直译为：足于～。 前面加名词或动词原形。 「～に足りない」还可以翻译成：没有必要～。","example":"例：彼は信頼に足る人物です。 例：こんなに高い実力なら、彼は恐れるに足りない。","translation":"译文：他是个值得信任的人。 译文：以这么高实力，他用不着害怕。"},{"point":"～さえ～ば","explain":"「甲斐」的意思是“价值”。全意为：有～的价值。","example":"例：苦労した甲斐がある。","translation":"译文：受的苦终于有了回报。"},{"point":"ただでさえ～","explain":"に表示方向或对象；は是强调；「当たる」的意思是“相当”。 前接名词和动词的原形。 全意为：不相当于～。意译为：没有必要～，值得～。","example":"例：彼の実力を考えると、今回の彼の受賞は驚くには当たらない。 例：彼の行為は称賛には当たらない。","translation":"译文：考虑到他的实力，就用不着对他这次的得奖感到吃惊。 译文：他的行为不值得称赞。"}]},{"category":"只是","items":[{"point":"～だけで","explain":"「と、ば、たら、なら」有很大区别，大致可以分成两个极端，と是条件性最强，なら是假设性最强。 条件性强的意思是：只要有某个条件就有某个结果。","example":"例：親と一緒にいると安心していられる。","translation":"译文：只要和父母在一起就会一直安心。"},{"point":"～だに","explain":"「限り」的意思是“极限”，和表示条件的と意思相同。","example":"例：親と一緒にいる限り、自由にはなれない。","translation":"译文：只要和父母在一起就不会自由。"},{"point":"～だけに","explain":"~ば 助词さえ接在名词后，ば表示的条件性强。 ただでさえ~ 「ただ」的汉字可以写成「唯，只，徒」等，这里理解成徒有空有；で表示程度；さえ的意思是“连～”。 全意为：本来就～，现在更加～。","example":"例：時間さえあれば、問題はないと思う。 例：ただでさえ怖い先生は、試験の日には余計怖く見える。","translation":"译文：我想，只要有时间就没有问题。 译文：本来就可怕的老师，考试当天看上去越发可怕。"},{"point":"～ばかりに","explain":"だけ的意思是“只”；で表示程度。","example":"例：単語を覚えるだけで語学力が向上しない。","translation":"译文：只是记单词外语能力不会提高。"},{"point":"～しかない","explain":"だ是「だけ」的意思；に表示副词。 前面一般接名词或动词，例如「想像する、考える、思い出す、聞く」等词。 语气正式、生硬。","example":"例：その事は考えるだに冷や汗が出る。","translation":"译文：那件事只是想想就出冷汗。"},{"point":"～ほかない","explain":"だけ的意思是“只是”；に表示副词。 全意为：只是因为～。 此处的因果关系不是通过だけに，而是通过上下文推测的。一般引起消极的结果。","example":"例：彼の指摘は正しいだけに、かえって私は反発を感じた。","translation":"译文：只是因为他对我的指正太正确了，反倒引起了我的逆反心理。"},{"point":"～に限って","explain":"ばかり的意思是“光是、全是、净是”；に表示副词。 全意为：全是因为～。 此处的因果关系不是通过ばかりに，而是通过上下文推测的。一般引起消极的结果。","example":"例：彼の言葉を信じたばかりに、ひどい目に遭った。","translation":"译文：全是因为我相信了他的话，结果倒了大量。"},{"point":"～に限らず","explain":"しか的意思是“只”，后面接否定。比だけ语气强。","example":"例：誰もいないので帰るしかない。","translation":"译文：没有人所以只有回去了。"},{"point":"～ならでは","explain":"「他」的意思是“其他”；ない是“没有”。 直译为：没有其他。 和「しかない」意思和用法一样，但是语气比「しかない」强。","example":"例：留学するお金がないので、留学を諦めるほかない。","translation":"译文：没有去留学的钱，所以只有放弃留学。"},{"point":"～まで(のこと)だ","explain":"「限る」的意思是“极限”；に表示方向或对象，前面接名词。 意思是：只限于～。","example":"例：簡単な問題に限って答えられない。","translation":"译文：越是简单的问题越回答不上来。"},{"point":"単なる～にすぎない","explain":"「限る」的意思是“极限”；ず是否定ない；に表示方向对象。前面接名词。 意思是：不只限于～。","example":"例：この講義は大学生に限らず、社会人も聴講できる。","translation":"译文：这个课不只限于大学生，工作的人也能听课。"},{"point":"わずか～足らずで","explain":"「なら」是「成る」的未然形，意思是“不成为～”；ではです的中顿；は表示强调。 意思是：如果不是～的话，就～。引申为：只有～，才有～。","example":"例：このチョコレートは今年のバレンタインデーならではのものです。 例：この人形は日本ならではのものです。","translation":"译文：这种巧克力只有今年的情人节才有。 译文：这种玩偶只有日本才有。"}]},{"category":"状态","items":[{"point":"～ている","explain":"までの意思是“到～的地步”，引申为：只有～。 加上「のこと」语气更为正式、生硬。 単なる~にすぎない 「単なる」的意思是“单单”；に表示方向或对象；「過ぎない」的意思是“不过”。 全意为：只不过～。 わずか~足らずで 「僅か」的意思是“仅仅”；「足らず」的意思是“不足”；で表示程度。 全意为：只有～。","example":"例：彼がしてくれなければ、他の人を探すまでだ。 例：彼には関係がないかもしれないが、念のため知らせたまでのことだ。 例：それは単なる言い訳にすぎない。 例：彼はわずか三か月足らずで日常会話を身につけた。","translation":"译文：他不帮我们做的话，我们只有找其他人了。 译文：可能跟他没有关系，只是为了保险起见才通知的。 译文：那只不过是个借口。 译文：他不到3个月就搞定了日常会话。"},{"point":"～てある","explain":"前面接自动词。","example":"例：電気がついている。","translation":"译文：灯开着呢。"}]},{"category":"转折","items":[{"point":"～が","explain":"前面接他动词。 有些动词只有一个表达方式，没有相对应的自动词或他动词，因此有自动词用「ている」和他动词用「てある」的不同表达方式。如果有相对应的自动词或他动词，那么就成为了一种说法有两种表达方式。 区别在于他动词着重于有人做。 用自动词还是用他动词的最关键的是“动作是谁做的”，他动词着重于有做的人。 注：单纯叙述。","example":"例：本は机の上に置いてある。 例：ドアは開いている。 例：ドアは開けてある。","translation":"译文：书放在桌子上。 译文：门开着。 译文：有人把门打开了，门开着。"},{"point":"～けれども","explain":"接续助词。表示顺接(单纯接续两个句子)、逆接(表示转折)、省略后句(为了柔和语气)的三个意思。","example":"例：メールを出したが、先方からの返事はまだ来ていない。","translation":"译文：发了邮件，但是对方还没回信。"},{"point":"～のに","explain":"是が的口语形式。此外还有けれど、けど按顺序语气柔和。 ども是古语的ても，意思是“即使、尽管、不管”。 表示顺接(单纯接续两个句子)、逆接(表示转折)、省略后句(为了柔和语气)的三个意思。","example":"例：無事に合格したけれども、理解の浅い内容はもう一度しっかり復習する必要がある。","translation":"译文：平安无事的及格了，但是理解不深的内容还要好好复习一遍。"},{"point":"～くせに","explain":"のに表示转折，有惊讶之意或表示“遗憾、后悔、生气、埋怨”等消极语气。 动词和形容词后直接加のに，形容动词和名词加な在加のに。","example":"例：彼女は日本語を半年しか習っていないのに、もうこんなにしゃべれるのよ。 例：もうくたくたなのに、残業しなければいけないと言われたら、たまらない。","translation":"译文：她才学了半年日语就这么能说了。 译文：已经累得不行了，还要让我加班，真受不了。"},{"point":"～ものを","explain":"「癖」的意思是“不好的嗜好”；に是变名词为副词。 「くせに」意思是“责怪他人”，而「のに」的用法广泛，除了可以责怪他人以外还有“惊讶”的意思，或表示“遗憾、后悔、生气、埋怨”等的消极的语气。 既可以用于他人还可以用于自己或事物等。在责怪他人时，「くせに」的语气比「のに」强。","example":"例：あの人は一人では何もできないくせに、会社ではいつも偉そうな顔をしている。","translation":"译文：那个人一个人什么都干不了，在公司里却老是显得自己比别人强似的。"},{"point":"～わりには","explain":"表示强调意思的「もの」加上有转折意思的助词「を」的形式。 和「のに」的意思用法基本一样。 语气正式、生硬。","example":"例：電話で簡単に済ませるものを、わざわざ会いに行く必要はないでしょう。","translation":"译文：在电话里就能简单地解决，有必要特地去见面吗？"},{"point":"～ながら","explain":"「わり」是「割る」的连用形，作名词使用，意思是“比例、比率”；に是变名词为副词；は表示强调。 意思是：按照比例比率却～。","example":"例：この靴は値段のわりには丈夫だ。","translation":"译文：这双鞋价格便宜却很结实。"},{"point":"～ものの","explain":"「ながら」有两个意思，一个是“一边～，一边～”，另一个表示转折。 在表示转折时有时为了加强语气后面加「も」。 前面接动词的连用形，形容词原形，形容动词和名词直接加或用「でありながら」。 代表性的词是「しかしながら」。","example":"例：狭いながらも快適な家です。","translation":"译文：是个虽然小但是很舒适的房子。"},{"point":"～つつ","explain":"「もの」接在句尾表示强调；「の」与「が」含义相同，表示转折。 常用的形式是「よかったものの」，意思是：幸亏～了，要不然肯定发生不好的事了。","example":"例：早く気づいたからよかったものの、気づかなかったら、事故になっていたかもしれない。","translation":"译文：早发现真是太幸运了，如果没注意可能已经出事故了。"},{"point":"～とはいえ","explain":"つつ表示反复或是继续，在此表示反复，可以理解为汉语的“次次”。 前面接动词的连用形构成复合词。 「ーつつ」后加「も」，表示强调。 表示转折，意思是：虽然次次～但是～。","example":"例：参考書を持って来なければと思いつつ、毎回忘れている。 例：遅刻するのはよくないと知りつつも、毎回遅刻してしまう。","translation":"译文：虽然次次想着必须带参考书来，可是每次都忘。 译文：虽然次次知道迟到不好，但是每次都迟到。"},{"point":"～といえども","explain":"と表示内容；は表示强调；「いえ」是「言う」的命令形，在日语古语里有使用动词的命令形表示转折的用法，这种用法除了「とはいえ」以外还有「であれ」(＝～であっても，即使是～)。 全意为：虽说～。 语气正式、生硬。","example":"例：あの子は幼いとはいえ、しっかりしている。","translation":"译文：虽说那个孩子还小，可是很懂事。"}]},{"category":"最好","items":[{"point":"～た方がいい","explain":"と表示内容；「言う」的意思是“说”；「ども」表示转折，意思是“即使、不管、尽管”，此外表示同样意思的还有「とも」和「ても」；ども表示转折的代表例为「けれども」。 全意为：虽说～。 语气比「とはいえ」更加正式、生硬。","example":"例：如何に多忙といえども、健康管理を怠ってはならない。","translation":"译文：不管多么忙，疏忽健康管理可不成。"},{"point":"～にしくはない","explain":"「方」强调几个方面的一个方面；が是强调前面的名词。 前面如果接动词的肯定形式则必须接过去式。","example":"例：朝電車の中は混むから早く家を出た方がいい。 例：あまり無理しない方がいいよ。","translation":"译文：早上车里挤，最好早些出门。 译文：最好别勉强。"}]},{"category":"最后","items":[{"point":"～を最後として","explain":"に表示方向或对象；「如く」的意思是“如～”；は表示强调；ない的意思是“没有”。 直译为：不如～，意译为：没有比～更好的了。","example":"例：用心するにしくはない。","translation":"译文：最好小心。"},{"point":"～を限りに","explain":"应用了日语的经典句型“～を～とする，把～当作～”。 意思是：把～当作最后。","example":"例：明日を最後としてみなさんとはお別れです。","translation":"译文：明天是最后一天，后天就要跟大家分别了。"},{"point":"～を以て","explain":"应用了日语的经典句型「～を～に(と)する(把～当作～)」。 「限り」的意思是“极限”。","example":"例：あの方は今月15日を限りに引退した。","translation":"译文：本月15号是工作的最后一天，那个人第二天引退了。"},{"point":"～たきり","explain":"意思是：以～为极限。","example":"例：本日を以て閉店させていただきます。","translation":"译文：以今天为最后期限，本店关门了。"}]},{"category":"做得困难","items":[{"point":"どうにか","explain":"「きり」是「切る」的连用形；前面的动词为过去式。 意思为：做完了～后动作中断，之后再也没有做过此事。","example":"例：渡辺先生とは昨年一度会ったきりです。 例：祖父は階段から転んでから、ずっと寝たきりだ。","translation":"译文：去年和渡边老师见过一面后再也没见过。 译文：祖父从台阶上摔下来后一直卧床不起。"},{"point":"からうじて","explain":"副词「どうにか」的意思是“虽然有很多困难，但是好歹～”。","example":"例：借金はどうにか返した。","translation":"译文：好歹把借来的钱还了。"},{"point":"なんとか","explain":"「辛うじて」是「辛くして」的音变。着重于“经历了痛苦，但是总算～”。","example":"例：辛うじて間に合った。","translation":"译文：总算赶上了。"}]},{"category":"作为","items":[{"point":"～として","explain":"「なんとか」的意思是“有很多困难”。","example":"例：なんとか合格した。 例：なんとかしてください。 例：なんとかなります。","translation":"译文：总算合格了。 译文：虽然知道有很多困难，请您务必想想办法。 译文：虽然有很多困难，但是总会有办法的。"},{"point":"～にしては","explain":"应用了日语的经典句型「～を～とする(把～当作～)」。と表示内容。","example":"例：今の話は友達としての助言だよ。","translation":"译文：刚才的话不容易懂。"},{"point":"～にしては","explain":"应用了日语的经典句型「～を～にする(把～当作～)」的活用。に表示对象；は表示强调。 必须是前后相反。","example":"例：彼は相撲選手にしては体型が小さい。","translation":"解释：他作为一个相扑选手体格太小了。"}]}]}});
